window.KB=[{"id":"01-1","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Sankosh divides it into Eastern and Western Dooars; Wikipedia gives the combined area as 880 km2, with elevation 90 to 1,750 m and \"18 passes\" between Bhutan hills and Indian plains","kind":"conflict","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"},{"l":"CONFLICT/likely error: 880 km2 is implausible fo","u":"https://ir.nbu.ac.in/bitstreams/7c0564ad-bca8-4590-aa36-446035813382/download"}]},{"id":"01-2","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Travel sources describe the Bengal Dooars as roughly 130 km (Teesta to Sankosh) x 40 km (rough rectangle, not a measured area)","kind":"operator","src":[{"l":"East Himalaya","u":"https://www.east-himalaya.com/dooars"}]},{"id":"01-3","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Assam portion (historical divisions): Eastern Dooars lie between Sankosh and Manas; Kamrup Dooars between Manas and Bornadi; Darrang Dooars between Bornadi and Dhansiri. Assam districts today: Kokrajhar, Chirang, Bongaigaon, Goalpara, Baksa, Udalguri etc. (BTR region)","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-4","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"West Bengal districts per Wikipedia: Kalimpong (foothills), Jalpaiguri, Alipurduar, upper part of Cooch Behar","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-5","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Jalpaiguri district: area 3,386 km2; 2011 population 2,381,596 (post-split); 9 CD blocks (Jalpaiguri, Maynaguri, Rajganj, Mal, Matiali, Nagrakata, Kranti, Dhupguri, Banarhat); 3 subdivisions (Jalpaiguri Sadar, Malbazar, Dhupguri); average annual rainfall 3,160 mm; Alipurduar carved out 25 June 2014","kind":"report","src":[{"l":"Wikipedia: Jalpaiguri district","u":"https://en.wikipedia.org/wiki/Jalpaiguri_district"}]},{"id":"01-6","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Gorumara (Jalpaiguri, Malbazar subdivision) is about 17 km from Mainaguri and about 80 km from Bagdogra airport","kind":"report","src":[{"l":"Wikipedia: Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"01-7","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Jaldapara and Chilapata are in Alipurduar district (nearest towns Madarihat, Birpara, Hasimara); Neora Valley NP is in Kalimpong district","kind":"report","src":[{"l":"Jaldapara","u":"https://en.wikipedia.org/wiki/Jaldapara_National_Park"},{"l":"Chilapata","u":"https://en.wikipedia.org/wiki/Chilapata_Forests"}]},{"id":"01-8","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Ecoregion: Terai-Duar savanna and grasslands","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-9","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Named rivers: Teesta, Torsha (Torsa), Jaldhaka, Sankosh, Raidak, Murti, Manas","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-10","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Jalpaiguri rivers: Dharla, Jaldhaka, Karala, Teesta, Torsha","kind":"report","src":[{"l":"Wikipedia: Jalpaiguri district","u":"https://en.wikipedia.org/wiki/Jalpaiguri_district"}]},{"id":"01-11","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Gorumara is on Jaldhaka, Murti and Raidak floodplains; Chapramari fed by Teesta, Neora, Jaldhaka, Murti; Jaldapara on Torsa; Buxa: Raidak and Jayanti rivers, Narathali lake","kind":"report","src":[{"l":"Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"},{"l":"Chapramari","u":"https://en.wikipedia.org/wiki/Chapramari_Wildlife_Sanctuary"}]},{"id":"01-12","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Jalpaiguri district rainfall: annual average 3,160 mm; wettest July (809.3 mm); driest December (0.2 mm)","kind":"report","src":[{"l":"Wikipedia: Jalpaiguri district","u":"https://en.wikipedia.org/wiki/Jalpaiguri_district"}]},{"id":"01-13","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Siliguri/Bagdogra normals 1991-2020 (nearby proxy): annual 3,011 mm over about 132 rainy days; July 843 mm, June 628 mm, August 589 mm; Nov and Dec about 10-11 mm; mean max 27.7 °C, mean min 18.7 °C; record high 41.9 °C, record low 1.9 °C; humidity 75% (about 90% in July)","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-14","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Elevation range 90 to 1,750 m (Wikipedia)","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-15","topic":"nature","ctx":"Gorumara NP (Jalpaiguri)","text":"Closed 16 June-15 September (monsoon); watchtowers: Jatraprasad, Rhino Observation Point, Chandrachur, Chukchuki, Medla","kind":"report","src":[{"l":"Wikipedia: Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"01-16","topic":"nature","ctx":"Gorumara NP (Jalpaiguri)","text":"Reopened 16 Sept 2024 (reported Monday after 3 months); about 200 tourists on the first day; entrances Ramsai, Murti, Gorumara main; 3 elephants for safari in 2024 (2 in 2023)","kind":"report","src":[{"l":"Millennium Post, 17 Sep 2024","u":"https://www.millenniumpost.in/bengal/gorumara-national-park-reopens-after-3-months-with-enhanced-safaris-and-new-attractions-579849"}]},{"id":"01-17","topic":"nature","ctx":"Gorumara NP (Jalpaiguri)","text":"Jeep safari tickets issued at Lataguri Nature Interpretation Centre counter (closed in closure period); online via WBFDC (July 2025 blog; not an official page)","kind":"operator","src":[{"l":"Resort Trimurti guide","u":"https://www.resorttrimurti.com/blog/dooars-jungle-safari-price-booking-best-time-complete-travel-guide"}]},{"id":"01-18","topic":"nature","ctx":"Jaldapara NP (Alipurduar)","text":"Area 216.51 km2; sanctuary 1941; national park May 2014; elevation 61 m; on Torsa; second largest rhino population in India after Kaziranga; 294 tree species (2016-18 survey)","kind":"report","src":[{"l":"Wikipedia: Jaldapara","u":"https://en.wikipedia.org/wiki/Jaldapara_National_Park"}]},{"id":"01-19","topic":"nature","ctx":"Jaldapara NP (Alipurduar)","text":"Online safari booking opened 14 Oct 2026: 912 safari seats/day across five routes (Salkumar, Madarihat, Lankapara, Chilapata, Kodalbasti); 48 elephant-ride seats bookable online; bookings up to one month in advance (full article paywalled)","kind":"report","src":[{"l":"UNI, 14 Oct 2026","u":"https://www.uniindia.com/east-india/tourism-wb-jaldapara-durga-puja/214066"}]},{"id":"01-20","topic":"nature","ctx":"Jaldapara NP (Alipurduar)","text":"Closure reported as 15 June-15 September by a travel site; no official notice found","kind":"unverified","src":[{"l":"GoTirupati summary via search","u":"https://gotirupati.com/?p=41289"}]},{"id":"01-21","topic":"nature","ctx":"Buxa Tiger Reserve (Alipurduar)","text":"Total 760.87 km2: core/critical tiger habitat 390.58, buffer 370.29 (NTCA brief, 2019 document, figures per search snippet)","kind":"official","src":[{"l":"NTCA Buxa brief","u":"https://ntca.gov.in/assets/uploads/briefnote/buxa.pdf"}]},{"id":"01-22","topic":"nature","ctx":"Buxa Tiger Reserve (Alipurduar)","text":"Tiger reserve 1983 (India's 15th); sanctuary 1986 (314.52 km2) +54.47 km2 in 1991; national park 117.10 km2 notified 5 Dec 1997; elevation 60 to 1,750 m; 284+ bird, 73 mammal, 65 fish, 41 reptile species; elephant corridor to Bhutan (Phibsoo WLS adjoining)","kind":"report","src":[{"l":"Wikipedia: Buxa","u":"https://en.wikipedia.org/wiki/Buxa_Tiger_Reserve"}]},{"id":"01-23","topic":"nature","ctx":"Buxa Tiger Reserve (Alipurduar)","text":"Tiger: photographed Dec 2021 after nearly three decades; latest confirmed sighting 31 Dec 2023; Bhutia Basti and Gangutia villages relocated from core; camera-trap census (2 sq km grids, 2 traps each, 45 days) planned from the last week of Jan 2026","kind":"official","src":[{"l":"Millennium Post, 25 Nov 2025","u":"https://www.millenniumpost.in/bengal/intensive-tiger-census-to-begin-in-january-2026-637004"}]},{"id":"01-24","topic":"nature","ctx":"Chapramari WLS (Jalpaiguri)","text":"960 hectares (about 9.6 km2); reserve forest 1895; sanctuary 1998; known for elephants and gaur; Teesta/Neora/Jaldhaka/Murti rivers; 2013 train collision killed 5 adults and 2 calves from a herd of 40-50","kind":"report","src":[{"l":"Wikipedia: Chapramari","u":"https://en.wikipedia.org/wiki/Chapramari_Wildlife_Sanctuary"}]},{"id":"01-25","topic":"nature","ctx":"Chilapata Forests (Alipurduar)","text":"Corridor linking Jaldapara and Buxa; about 40 km from Alipurduar town, near Hasimara; Naranarayan Garh ruins; leopards common; area not given","kind":"report","src":[{"l":"Wikipedia: Chilapata","u":"https://en.wikipedia.org/wiki/Chilapata_Forests"}]},{"id":"01-26","topic":"nature","ctx":"Neora Valley NP (Kalimpong)","text":"88 km2 per Wikipedia; established 1986; elevation 183-3,200 m; red panda, clouded leopard, golden cat; tiger photographed 2017 (first in 40 years) and Dec 2023","kind":"conflict","src":[{"l":"Wikipedia: Neora Valley","u":"https://en.wikipedia.org/wiki/Neora_Valley_National_Park"},{"l":"Millennium Post, Nov 2025","u":"https://www.millenniumpost.in/bengal/intensive-tiger-census-to-begin-in-january-2026-637004"}]},{"id":"01-27","topic":"nature","ctx":"Fees (all third-party, unverified)","text":"Jeep safari per jeep: INR 2,500-4,000 (Gorumara/Chapramari), INR 3,500-4,500 (Jaldapara); elephant safari about INR 1,000-1,500 per person (2026 travel guide)","kind":"unverified","src":[{"l":"Resort Trimurti","u":"https://www.resorttrimurti.com/blog/dooars-jungle-safari-price-booking-best-time-complete-travel-guide"}]},{"id":"01-28","topic":"nature","ctx":"Fees (all third-party, unverified)","text":"Another site lists elephant safari Rs 140 and entry Rs 25 per adult: likely outdated","kind":"old","src":[]},{"id":"01-29","topic":"nature","ctx":"Wildlife counts from censuses","text":"Rhino census 5-6 March 2025: Jaldapara 331 (range 327-334), Gorumara 61 (58-63), total 392; 2019 total 289 (Jaldapara 237, Gorumara 52); 2013 total 229","kind":"conflict","src":[{"l":"Millennium Post, 19 Mar 2025","u":"https://www.millenniumpost.in/bengal/rhino-population-in-jaldapara-and-gorumara-rises-to-392-602935"},{"l":"AIR","u":"https://newsonair.gov.in/great-one-horned-rhinoceros-population-in-west-bengal-increases-to-392"}]},{"id":"01-30","topic":"nature","ctx":"Wildlife counts from censuses","text":"Elephants North Bengal: 488 (2017 census; Darjeeling, Jalpaiguri, Alipurduar, under 2% of national)","kind":"report","src":[{"l":"Lok Sabha document","u":"https://eparlib.sansad.in/bitstream/123456789/2981872/1/1015.pdf"}]},{"id":"01-31","topic":"nature","ctx":"Wildlife counts from censuses","text":"Elephants North Bengal about 676 in the latest survey (Oct 2025 report; national forest elephants 22,446 vs 29,964 in 2017)","kind":"conflict","src":[{"l":"Millennium Post, 18 Oct 2025","u":"https://www.millenniumpost.in/nation/north-bengal-sees-rise-in-elephant-population-amid-national-decline-631744"},{"l":"CONFLICT: Down To Earth says about 630 in north ","u":"https://www.downtoearth.org.in/agriculture/conflict-in-the-backyard-community-patrols-cut-crop-damage-in-north-bengal-but-south-bengals-farmers-remain-exposed"}]},{"id":"01-32","topic":"nature","ctx":"Wildlife counts from censuses","text":"Tigers: Buxa one resident in 2005 ; recent camera evidence 2021, 2023 (above)","kind":"old","src":[]},{"id":"01-33","topic":"nature","ctx":"Wildlife counts from censuses","text":"Gorumara species totals: 194 birds, 50 mammals; Buxa 284+ birds, 73 mammals (above)","kind":"report","src":[]},{"id":"01-34","topic":"nature","ctx":"Wildlife counts from censuses","text":"Gaur: present in Gorumara, Jaldapara and Chapramari; no official count found.","kind":"report","src":[]},{"id":"01-35","topic":"nature","ctx":"Elephant corridors and human-wildlife conflict relevant to visitors","text":"Train deaths in north Bengal: over 50 elephants 2004-2013; about 30 more 2013-2023, mainly on Madarihat-Hasimara and Rajabhatkhawa-Alipurduar Junction stretches; none in past two years per a forest official; AI thermal-camera detection works at 700-750 m","kind":"report","src":[{"l":"News Arena","u":"https://newsarenaindia.com/states/ai-forest-railways-collaboration-cuts-elephant-deaths-n-bengal/68923"}]},{"id":"01-36","topic":"nature","ctx":"Elephant corridors and human-wildlife conflict relevant to visitors","text":"Crop-raiding seasons: corn mid-May to end July; paddy mid-Sept to Nov; lone elephants raid houses Dec-Jan. Community Quick Response Teams use walkie-talkies; farmers report damage cut by up to 90%","kind":"report","src":[{"l":"Down To Earth","u":"https://www.downtoearth.org.in/agriculture/conflict-in-the-backyard-community-patrols-cut-crop-damage-in-north-bengal-but-south-bengals-farmers-remain-exposed"}]},{"id":"01-37","topic":"nature","ctx":"Elephant corridors and human-wildlife conflict relevant to visitors","text":"State compensation for wildlife damage: Rs 12.7 crore (2023-24), Rs 10.17 crore (2024-25) (state-wide, not North Bengal)","kind":"report","src":[]},{"id":"01-38","topic":"nature","ctx":"Elephant corridors and human-wildlife conflict relevant to visitors","text":"Visitor advisory: Gorumara walking on metalled roads allowed but unsafe due to elephants, gaur and rhino","kind":"report","src":[{"l":"Wikipedia: Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"01-39","topic":"nature","ctx":"Elephant corridors and human-wildlife conflict relevant to visitors","text":"Rhino/safari suspended during census (March 2025)","kind":"official","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/rhino-census-underway-in-north-bengal-forests-jungle-safaris-remain-suspended-601240"}]},{"id":"03-40","topic":"places","ctx":"Region framing","text":"Dooars: alluvial floodplain about 30 km wide, about 350 km long, Teesta to Dhansiri; Sankosh divides Eastern and Western Dooars. Wikipedia notes the article needs more citations.","kind":"report","src":[{"l":"Wikipedia Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"03-41","topic":"places","ctx":"Region framing","text":"Main gateways: Bagdogra airport and NJP; stations in region include Malbazar, Hasimara, Alipurduar, Cooch Behar; private car from Bagdogra/NJP recommended.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-42","topic":"places","ctx":"Region framing","text":"Bagdogra to NJP is about 18 km / about 45 min by taxi; shared taxis NJP to Gorumara/Jaldapara generally not available, prepaid taxis used.","kind":"operator","src":[{"l":"darjeeling-tourism.com","u":"https://darjeeling-tourism.com/darj_000206.htm"}]},{"id":"03-43","topic":"places","ctx":"Region framing","text":"Seasons: Oct-Mar peak; Apr-May warm; Jun-Sep monsoon with forest closures.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-44","topic":"places","ctx":"Lataguri (Gorumara gateway)","text":"Main town and park entrance on NH717; hub for Gorumara resorts; Ramsai is the other side of the park.","kind":"report","src":[{"l":"Wikipedia Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"03-45","topic":"places","ctx":"Lataguri (Gorumara gateway)","text":"About 85 km from NJP by the traditional route, or about 53 km via Gajoldoba.","kind":"operator","src":[{"l":"north-bengal.com Gorumara","u":"https://north-bengal.com/gorumara-national-park-dooars.php"},{"l":"north-bengal search summary","u":"https://northbengaltourism.com/tour-packages/dooars/nbthp0006"}]},{"id":"03-46","topic":"places","ctx":"Lataguri (Gorumara gateway)","text":"Nearest railheads: New Mal Junction (about 18 km) and New Maynaguri; Maynaguri to Lataguri about 20 min.","kind":"report","src":[{"l":"Wikipedia Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"03-47","topic":"places","ctx":"Lataguri (Gorumara gateway)","text":"Permits mandatory, booked in advance via Lataguri Forest Office or authorised agents; open-jeep safaris twice daily with licensed guide.","kind":"operator","src":[{"l":"north-bengal.com Gorumara","u":"https://north-bengal.com/gorumara-national-park-dooars.php"}]},{"id":"03-48","topic":"places","ctx":"Lataguri (Gorumara gateway)","text":"Stay: Lataguri main hub, Murti quieter, Chalsa more upscale, Ramsai rural; weak mobile network at Murti and Ramsai.","kind":"operator","src":[{"l":"north-bengal.com Gorumara","u":"https://north-bengal.com/gorumara-national-park-dooars.php"}]},{"id":"03-49","topic":"places","ctx":"Gorumara National Park","text":"Coordinates 26°42′N 88°48′E; area 79.99 km2; Malbazar subdivision, Jalpaiguri; 50 mammal and 194 bird species recorded; leopard only resident big cat; tigers only occasionally seen.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"03-50","topic":"places","ctx":"Gorumara National Park","text":"Towers/points: Jatraprasad, Rhino Observation Point, Chandrachur, Chukchuki (birding), Medla. Wikipedia states no elephant-back or ranger-led forays and that walking on metalled roads is allowed but risky.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"03-51","topic":"places","ctx":"Gorumara National Park","text":"Closure: 16 Jun to 15 Sep; best Nov-Mar (Wikipedia); Oct to early April (north-bengal.com).","kind":"operator","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"},{"l":"north-bengal.com","u":"https://north-bengal.com/gorumara-national-park-dooars.php"}]},{"id":"03-52","topic":"places","ctx":"Gorumara National Park","text":"Fees (secondary, rough): Rs 100 per person entry, 6am-5pm; jeep safari about Rs 1,500-2,500 per jeep (up to 6); elephant safari Rs 1,000-1,500 per person.","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-53","topic":"places","ctx":"Chapramari Wildlife Sanctuary","text":"Extension of Gorumara across Murti river; entry Rs 70 per person; 6am-6pm; open 15 Oct-15 Jun (secondary).","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-54","topic":"places","ctx":"Chapramari Wildlife Sanctuary","text":"Forms wildlife corridor with Gorumara; known for elephants and gaur.","kind":"operator","src":[{"l":"north-bengal.com Gorumara","u":"https://north-bengal.com/gorumara-national-park-dooars.php"},{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-55","topic":"places","ctx":"Murti / Rocky Island","text":"Murti: forest bungalow near Chandrachur tower; Murti River flows along park floodplain.","kind":"report","src":[{"l":"Wikipedia Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"03-56","topic":"places","ctx":"Murti / Rocky Island","text":"Rocky Island: rocks beside Murti river; camping, bonfire, stargazing; listed best mid-Oct to Dec.","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-57","topic":"places","ctx":"Chalsa and Malbazar (tea-belt bases)","text":"Described as tea-garden bases of western Dooars; Malbazar called a melting pot of cultures.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-58","topic":"places","ctx":"Chalsa and Malbazar (tea-belt bases)","text":"Chalsa about 40 km, Murti 43 km, Lataguri 61 km from Bindu (route-based).","kind":"operator","src":[{"l":"north-bengal.com Bindu","u":"https://www.north-bengal.com/bindu-dooars-dooars.php"}]},{"id":"03-59","topic":"places","ctx":"Chalsa and Malbazar (tea-belt bases)","text":"Wikipedia page for Mal Bazar returned 404 at the URL tried; no coordinates found.","kind":"report","src":[]},{"id":"03-60","topic":"places","ctx":"Nagrakata, Banarhat, Birpara (tea estates)","text":"Listed as tea-garden areas offering plantation walks and settlement visits.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-61","topic":"places","ctx":"Samsing and Suntalekhola","text":"Samsing: small hill village at about 3,000 ft, Jalpaiguri district, approx 26°59′24″N 88°48′42″E; Neora Valley NP stated about 18 km away (also \"about an hour\"); fog, heavy rainfall; Bhutan hills visible on clear days.","kind":"report","src":[{"l":"Wikipedia Samsing","u":"https://en.wikipedia.org/wiki/Samsing"}]},{"id":"03-62","topic":"places","ctx":"Samsing and Suntalekhola","text":"Suntalekhola: offbeat village at edge of Neora Valley with tea gardens, river, wooden-bridge walk; free; listed Sep-Feb.","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-63","topic":"places","ctx":"Neora Valley National Park","text":"Kalimpong district; 27°04′N 88°42′E; 88 km2; established 1986; elevation 183-3,200 m; red panda habitat; much of park inaccessible.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Neora_Valley_National_Park"}]},{"id":"03-64","topic":"places","ctx":"Neora Valley National Park","text":"Treks reachable from Todey and Tangta (about an hour from Bindu) need Forest Dept permission.","kind":"operator","src":[{"l":"north-bengal.com Bindu","u":"https://www.north-bengal.com/bindu-dooars-dooars.php"}]},{"id":"03-65","topic":"places","ctx":"Neora Valley National Park","text":"The Dooars guide treats Neora as separate from the Dooars circuit.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-66","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Bindu: about 110 km from NJP, 115 km from Bagdogra; Jhalong about 10 km before Bindu; Paren homestay about 6 km from Bindu Dam; Jaldhaka hydel dam site not enterable, viewable from distance; limited accommodation (budget homestays, eco-resorts); Jhalong has a WBFDC tourist lodge.","kind":"operator","src":[{"l":"north-bengal.com Bindu","u":"https://www.north-bengal.com/bindu-dooars-dooars.php"}]},{"id":"03-67","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Weekly markets: Jhalong Wednesday market; Bhutanese visitors come to Bindu weekly market. Carry photo ID in border areas. Jhalong to Bindu stated 5 km by one source and 10 km by another.","kind":"operator","src":[{"l":"search summary of north-bengal.com / riddhimart ","u":"https://www.north-bengal.com/jhalong-dooars.php"}]},{"id":"03-68","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Jaldhaka hydel project is among the oldest India-Bhutan hydroelectric projects, at the meeting of Dudh Khola, Bindu Khola and Jaldhaka.","kind":"operator","src":[{"l":"north-bengal.com Bindu","u":"https://www.north-bengal.com/bindu-dooars-dooars.php"}]},{"id":"03-69","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Paren: about 112 km from Siliguri, railhead Malbazar then Chalsa then jeep; Rachella Pass is best-known trek; Jaldhaka about 10 km. Homestay: Khambuhang Nature Camp.","kind":"report","src":[{"l":"Tale of 2 Backpackers (2017)","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-70","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Gairibas: described as a viewpoint over the Jaldhaka winding through forested ridges; no distance found.","kind":"operator","src":[{"l":"search summary","u":"https://www.north-bengal.com/bindu-dooars-dooars.php"}]},{"id":"03-71","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Dalgaon: village among tea and ipecac, about 125 km from Siliguri, Bhutan-hill and Jaldhaka views; shared jeeps from Siliguri.","kind":"report","src":[{"l":"Tale of 2 Backpackers","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-72","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Rongo: hamlet, about 33 km from New Mal Jn, about 96 km from NJP; monastery and waterfall.","kind":"report","src":[{"l":"Tale of 2 Backpackers","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-73","topic":"places","ctx":"Jaldapara National Park / Madarihat / Hollong","text":"Alipurduar district, on Torsa; 26°41′27″N 89°16′35″E; 216.51 km2; largest rhino population in West Bengal, second in India after Kaziranga; nearest towns Madarihat and Birpara.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Jaldapara_National_Park"}]},{"id":"03-74","topic":"places","ctx":"Jaldapara National Park / Madarihat / Hollong","text":"NJP/Bagdogra to Jaldapara about 135 km, 3.5-4 hours (operator).","kind":"operator","src":[{"l":"northbengaltourism.com","u":"https://northbengaltourism.com/tour-packages/dooars/nbthp0006"}]},{"id":"03-75","topic":"places","ctx":"Jaldapara National Park / Madarihat / Hollong","text":"Entry Rs 60 per person; 6am-5pm; Oct-Jun (secondary); jeep safari about Rs 2,000-3,000 per jeep.","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-76","topic":"places","ctx":"Jaldapara National Park / Madarihat / Hollong","text":"Madarihat is main access point with hotels, resorts, homestays; Holong Forest Bungalow historically important; elephant rides historically offered at Holong, availability depends on forest rules.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-77","topic":"places","ctx":"Totopara (Toto tribe)","text":"Village in Madarihat-Birpara block, Alipurduar; 26°50′N 89°19′E; Bhutan foothills north, Torsa east; about 22 km from Madarihat via NH31/Hantapara single-lane road; 2011 population 2,960; Toto identification tagged \"citation needed\" on Wikipedia.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Totopara"}]},{"id":"03-78","topic":"places","ctx":"Totopara (Toto tribe)","text":"Offered as add-on to Jaldapara packages with jeep safari.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-79","topic":"places","ctx":"Chilapata Forest (Hasimara / Kalchini belt)","text":"26°33′02″N 89°22′47″E; about 40 km from Alipurduar, few minutes from Hasimara; elephant corridor Jaldapara-Buxa; ruins of Naranarayan Garh (Nalraja Garh) poorly maintained but archaeologically interesting; WBSFDA eco-resort at Kodalbasti; tonga rides in Mathura tea garden, boating on Bania, angling at Kalchini/Bania/Buri Basra confluence.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Chilapata_Forest"}]},{"id":"03-80","topic":"places","ctx":"Chilapata Forest (Hasimara / Kalchini belt)","text":"About 145 km from Siliguri; nearest stations New Alipurduar 26 km and Hasimara 16 km (blog); not officially a sanctuary or national park; forests generally closed Jun-Sep. Stays: Chilapata Jungle Camp, Chilapata Inn (Mendabari), 2017 data.","kind":"report","src":[{"l":"Tale of 2 Backpackers","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-81","topic":"places","ctx":"Chilapata Forest (Hasimara / Kalchini belt)","text":"Note the two sources disagree on station distances to Chilapata vs 40 km to Alipurduar (different reference points); verify.","kind":"report","src":[]},{"id":"03-82","topic":"places","ctx":"Alipurduar (district HQ)","text":"26°29′20″N 89°31′37″E; urban agglomeration population 127,342 (2011); stations Alipurduar Junction and New Alipurduar; NFR division HQ; Bagdogra about 150 km by road; Cooch Behar airport about 30 km.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Alipurduar"}]},{"id":"03-83","topic":"places","ctx":"Hasimara, Kalchini, Hamiltonganj, Rajabhatkhawa (rail/town nodes)","text":"Hasimara is a rail station region node; Rajabhatkhawa is the main Buxa gateway with railway station, Nature Interpretation Centre, forest facilities, and the widest accommodation choice.","kind":"operator","src":[{"l":"east-himalaya.com Buxa","u":"https://www.east-himalaya.com/buxa.php"},{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-84","topic":"places","ctx":"Hasimara, Kalchini, Hamiltonganj, Rajabhatkhawa (rail/town nodes)","text":"Hamiltonganj, Kalchini: no dedicated sourced data found.","kind":"report","src":[]},{"id":"03-85","topic":"places","ctx":"Buxa Tiger Reserve","text":"Alipurduar district, 26°39′0″N 89°34′48″E, 760 km2; 15th tiger reserve (1983); national park 117.10 km2 notified Dec 1997; 284 bird species; only one resident tiger as of 2005 (stale).","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Buxa_Tiger_Reserve"}]},{"id":"03-86","topic":"places","ctx":"Buxa Tiger Reserve","text":"Closure stated as 16 Jun to 15 Sep, check latest notification; Buxa Bird Festival in January; no Inner Line Permit, but forest areas require permission.","kind":"operator","src":[{"l":"east-himalaya.com Buxa","u":"https://www.east-himalaya.com/buxa.php"}]},{"id":"03-87","topic":"places","ctx":"Buxa Tiger Reserve","text":"Entry Rs 150 per person, 6am-5pm, 15 Oct-15 Jun (secondary, unverified).","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-88","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Santalabari: road-end start for Buxa Fort trek, about 2 hours on foot; guide required at counter (about Rs 280 in a Team-BHP travelogue; 2019 blog: Rs 250 fort, Rs 300 Lepchakha; stale).","kind":"operator","src":[{"l":"east-himalaya.com","u":"https://www.east-himalaya.com/buxa.php"},{"l":"Team-BHP","u":"https://www.team-bhp.com/forum/assembly-line/215568-dooars-purulia.html"}]},{"id":"03-89","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Buxa Fort: ruins, British-era detention camp for political prisoners; distance 2.5-5 km uphill depending on source (conflict).","kind":"operator","src":[{"l":"east-himalaya.com","u":"https://www.east-himalaya.com/buxa.php"},{"l":"Taleof2Backpackers","u":"https://taleof2backpackers.com/trekkers-paradise-buxa-fort/"}]},{"id":"03-90","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Rovers Point: about 3-4 km beyond fort at about 4,500 ft; Rs 100 permit in one guide; best Oct, Nov, Feb, Mar.","kind":"report","src":[{"l":"India Guide","u":"https://notify.india-guide.in/destinations/alipurduar/trekking"}]},{"id":"03-91","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Lepchakha: Drukpa/Dukpa settlement above fort, basic homestays (Wangmo Homestay, Lepchakha Jungle Camp, 2017 data), about 5.5 km trek from Santalabari.","kind":"operator","src":[{"l":"east-himalaya.com","u":"https://www.east-himalaya.com/buxa.php"},{"l":"Tale of 2 Backpackers","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-92","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Jayanti: village on stony Jayanti river bed; Buxa Fort-Jayanti trek about 13 km per forest dept, needs a guide; access affected by monsoon floods; Mahakal cave near river (blog).","kind":"operator","src":[{"l":"east-himalaya.com","u":"https://www.east-himalaya.com/buxa.php"},{"l":"Tripoto","u":"https://www.tripoto.com/jalpaiguri/trips/buxa-fort-jayanti-trek-5e9947b96082e"}]},{"id":"03-93","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Raimatang: forest village, about 74 km from Siliguri (UNVERIFIED, looks too short against Alipurduar-based distances), tea gardens, birding, trek to Lepchakha; Raimatang Mountain View Homestay (2017).","kind":"report","src":[{"l":"Tale of 2 Backpackers","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-94","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Other lesser-visited forest areas: Khuttimari, Titi, Apalchand, Kathambari (birdwatching).","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-95","topic":"places","ctx":"COOCH BEHAR AND BORDER AREAS","text":"Cooch Behar Palace (Rajbari): 26°19′37″N 89°26′19″E; built 1887 under Maharaja Nripendra Narayan; Italian Renaissance, about 51,309 sq ft, Durbar Hall dome about 124 ft; ASI monument of national importance; now museum.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Cooch_Behar_Palace"}]},{"id":"03-96","topic":"places","ctx":"COOCH BEHAR AND BORDER AREAS","text":"Timings/fees (conflicting): most say 10am-5pm, closed Friday (one says Tuesday), Indian fee Rs 10-25 (one lists Rs 250), foreigners Rs 250, light-and-sound show reported Fri/Sat 6-8pm.","kind":"operator","src":[{"l":"Holidify, Audiala, Indiano, Travelsetu etc. via ","u":"https://www.holidify.com/places/cooch-behar/rajbari-sightseeing-4432.html"}]},{"id":"03-97","topic":"places","ctx":"BHUTAN-GATEWAY TOWNS","text":"Phuentsholing (Bhutan): 26°51′N 89°23′E, elevation 293 m, Chukha district seat; adjoins Jaigaon; Bhutan Gate; Indian tourists need no visa but need ID and a permit at Phuentsholing; no airport or railway (Hasimara-linked rail was only planned).","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Phuentsholing"}]},{"id":"03-98","topic":"places","ctx":"BHUTAN-GATEWAY TOWNS","text":"Jaigaon: described as larger and busier than Phuentsholing; Jaigaon-Phuentsholing is the main India-Bhutan crossing.","kind":"operator","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Phuentsholing"},{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-99","topic":"places","ctx":"BHUTAN-GATEWAY TOWNS","text":"Alipurduar is described as a gateway to Bhutan.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Alipurduar"}]},{"id":"03-100","topic":"places","ctx":"Other","text":"South Khayerbari: rescued-animal centre (about 18 leopards), 10am-4pm, listed for monsoon season; battery-car tours (secondary).","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-101","topic":"places","ctx":"Heritage sites","text":"Buxa Fort: British detention camp for political prisoners; ruins only.","kind":"operator","src":[{"l":"east-himalaya.com","u":"https://www.east-himalaya.com/buxa.php"}]},{"id":"03-102","topic":"places","ctx":"Heritage sites","text":"Naranarayan Garh (Nalraja Garh) at Chilapata: ruins.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Chilapata_Forest"}]},{"id":"03-103","topic":"places","ctx":"Trekking and nature","text":"See Buxa and Paren entries in section 1: Fort-Jayanti about 13 km; Rovers Point best Oct-Nov, Feb-Mar; Neora treks need Forest Dept permission from Todey/Tangta; Jaldhaka riverside, Murti/Rocky Island camping, Chukchuki for birds, Buxa Bird Festival in January.","kind":"report","src":[]},{"id":"03-104","topic":"places","ctx":"Trekking and nature","text":"Chilapata: boating on Bania, angling at confluence.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Chilapata_Forest"}]},{"id":"04-105","topic":"culture","ctx":"District context (Census 2011)","text":"Alipurduar district: population 1,491,250 (rural 1,183,704; urban 307,456); Scheduled Castes 456,706 (30.62%); Scheduled Tribes 382,112 (25.62%). Religion: Hindu 80.07%, Muslim 8.74%, Christian 7.52%, Buddhist 2.37%, tribal religion 1.00%. Christians, Buddhists and tribal-religion followers are concentrated in tea-garden areas","kind":"report","src":[{"l":"Wikipedia, Alipurduar district (orientation; cit","u":"https://en.wikipedia.org/wiki/Alipurduar_district"}]},{"id":"04-106","topic":"culture","ctx":"District context (Census 2011)","text":"Alipurduar first languages (2011): Bengali 53.93%, Sadri 16.80%, Nepali 9.70%, Hindi 3.67%, Rajbongshi 3.17%, Kurukh (Oraon) 3.13%, Boro 2.38%, Bhojpuri 1.39%, Santali 1.32%, Rabha 1.23%","kind":"report","src":[{"l":"Wikipedia, Alipurduar district","u":"https://en.wikipedia.org/wiki/Alipurduar_district"}]},{"id":"04-107","topic":"culture","ctx":"District context (Census 2011)","text":"Alipurduar II block: STs 40,245 (18.44%); tribal concentration is highest in the three northern blocks","kind":"report","src":[{"l":"search summary of Wikipedia/Census block pages","u":"https://en.wikipedia.org/wiki/Alipurduar_II"}]},{"id":"04-108","topic":"culture","ctx":"District context (Census 2011)","text":"Present-day (post-2014) Jalpaiguri district: population 2,381,596; STs 349,592 (14.68%); Hindu 82.41%, Muslim 13.25%, Christian 3.12% (74,188), Buddhist 0.64% (15,358)","kind":"report","src":[{"l":"Wikipedia, Jalpaiguri district (cites Census 201","u":"https://en.wikipedia.org/wiki/Jalpaiguri_district"}]},{"id":"04-109","topic":"culture","ctx":"Toto (Totopara, Madarihat-Birpara block, Alipurduar)","text":"Totopara lies on the western bank of the Torsa near the Bhutan border","kind":"report","src":[{"l":"The Federal, March 2021","u":"https://thefederal.com/the-eighth-column/a-small-tribes-struggle-to-balance-development-and-cultural-identity"}]},{"id":"04-110","topic":"culture","ctx":"Toto (Totopara, Madarihat-Birpara block, Alipurduar)","text":"Population trajectory: 171 (1901); 321 in 69 houses (1951); 926 in 180 houses (1991); 1,184 (2001, all in Totopara); 1,389 (Census 2011); Toto Kalyan Samiti claimed 1,616 in 2021","kind":"report","src":[{"l":"The Federal","u":"https://thefederal.com/the-eighth-column/a-small-tribes-struggle-to-balance-development-and-cultural-identity"},{"l":"Wikipedia, Toto people (orientation)","u":"https://en.wikipedia.org/wiki/Toto_people"}]},{"id":"04-111","topic":"culture","ctx":"Toto (Totopara, Madarihat-Birpara block, Alipurduar)","text":"Totopara village total in Census 2011 was 2,960 (1,568 M / 1,392 F); Federal says Totos are about 27% of a village of about 6,000 (2021 estimate), with Nepalis now the largest group, including Lhotshampa refugees from Bhutan since the 1990s","kind":"report","src":[{"l":"Wikipedia, Totopara","u":"https://en.wikipedia.org/wiki/Totopara"},{"l":"The Federal","u":"https://thefederal.com/the-eighth-column/a-small-tribes-struggle-to-balance-development-and-cultural-identity"}]},{"id":"04-112","topic":"culture","ctx":"Toto (Totopara, Madarihat-Birpara block, Alipurduar)","text":"Language: Tibeto-Burman, no script until Dhaniram Toto developed one (2015); Unicode accepted it Oct 2019, in Unicode 14.0 (Sept 2021); Padma recognition reported by Times of India 28 Jan 2023","kind":"report","src":[{"l":"Wikipedia, Toto people","u":"https://en.wikipedia.org/wiki/Toto_people"},{"l":"The Federal","u":"https://thefederal.com/the-eighth-column/a-small-tribes-struggle-to-balance-development-and-cultural-identity"}]},{"id":"04-113","topic":"culture","ctx":"Toto (Totopara, Madarihat-Birpara block, Alipurduar)","text":"Religion: nature worship; two main deities Ishpa (linked to Bhutan hills; animal sacrifice and Eu offered) and Cheima (protector of village; rice, fowl, Eu); a few converts to Christianity","kind":"report","src":[{"l":"Wikipedia, Toto people","u":"https://en.wikipedia.org/wiki/Toto_people"},{"l":"Springer study on Eu","u":"https://link.springer.com/10.1186/s42779-021-00093-5"}]},{"id":"04-114","topic":"culture","ctx":"Toto (Totopara, Madarihat-Birpara block, Alipurduar)","text":"Livelihood: betel nut sales are the primary income; maize; kitchen gardens; trade in Bhutanese goods; transition from communal to individual land holding","kind":"report","src":[{"l":"Wikipedia, Toto people","u":"https://en.wikipedia.org/wiki/Toto_people"},{"l":"The Federal","u":"https://thefederal.com/the-eighth-column/a-small-tribes-struggle-to-balance-development-and-cultural-identity"}]},{"id":"04-115","topic":"culture","ctx":"Toto (Totopara, Madarihat-Birpara block, Alipurduar)","text":"Community concerns: language loss, request to reserve village land for Totos, cultural dilution through intermarriage, land pressure","kind":"report","src":[{"l":"The Federal","u":"https://thefederal.com/the-eighth-column/a-small-tribes-struggle-to-balance-development-and-cultural-identity"}]},{"id":"04-116","topic":"culture","ctx":"Rabha, Mech/Bodo, others","text":"In West Bengal Rabha live mainly in Jalpaiguri and Cooch Behar, about 70% of them in Jalpaiguri; the Dooars is regarded as the hub; music uses instruments like flute and singa (secondary: Indianetzone / Wikipedia mirrors)","kind":"report","src":[{"l":"Rabha tribe summary","u":"https://www.indianetzone.com/10/rabha_tribe.htm"}]},{"id":"04-117","topic":"culture","ctx":"Rabha, Mech/Bodo, others","text":"Mech/Bodo are a prominent tribal group in Jalpaiguri, Cooch Behar and Darjeeling; nature worship with Bathou as chief deity; Bwisagu is the new-year festival (the Bwisagu source is largely Assam-focused)","kind":"official","src":[{"l":"NBU thesis repository","u":"https://ir.nbu.ac.in/bitstreams/63b0f67d-e493-4904-a0c3-e548cef0ebb2/download"},{"l":"Assam Tourism festivals","u":"https://assamtourism.gov.in/festival-month.php"}]},{"id":"04-118","topic":"culture","ctx":"Rabha, Mech/Bodo, others","text":"A Bodo community in Kalchini block, Alipurduar has celebrated Durga Puja with its own cultural features for 55 years (Millennium Post, 2024)","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/bodo-community-celebrates-55-yrs-of-unique-puja-tradition-581965"}]},{"id":"04-119","topic":"culture","ctx":"Rabha, Mech/Bodo, others","text":"Dooars communities listed by a travel site: Rajbanshi, Mech, Rava (Rabha), Toto, Limboo, Lepcha, Bengali, Nepali","kind":"operator","src":[{"l":"north-bengal.com","u":"https://north-bengal.com/dooars.html"}]},{"id":"04-120","topic":"culture","ctx":"Rabha, Mech/Bodo, others","text":"Organisers describe the Dooars as having 26 tribal communities (festival claim, Millennium Post Jan 2024-25)","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/world-dooars-utsav-a-vibrant-celebration-of-culture-and-diversity-593222"}]},{"id":"04-121","topic":"culture","ctx":"Rajbongshi / Koch","text":"Koch Rajbongshi are an indigenous community of the Koch Bihar region, mostly Hindu, some following Khavas Tharu animist belief","kind":"report","src":[{"l":"Wikipedia mirror, Rajbongshi people","u":"https://ipfs.ssi.eecc.de/ipns/en.wikipedia-on-ipfs.org/wiki/Rajbongshi_people"},{"l":"kamatablog","u":"https://kamatablog.blogspot.com/2019/10/population-structure-of-cooch-behar-part-of-ratnapith-around-125-years-ago.html"}]},{"id":"04-122","topic":"culture","ctx":"Rajbongshi / Koch","text":"Rajbongshi is an additional official language of West Bengal alongside Bengali and English (listed on Cooch Behar page)","kind":"report","src":[{"l":"Wikipedia, Cooch Behar","u":"https://en.wikipedia.org/wiki/Cooch_Behar"}]},{"id":"04-123","topic":"culture","ctx":"Cooch Behar demographics (2011)","text":"Cooch Behar municipality 77,935; urban agglomeration 289,434; municipal religion Muslim 25.54%; mother tongue Bengali 83.6%, Hindi 13.9%, Nepali 1.09% (Wikipedia gives inconsistent Hindu share, 74.05% vs 76.44%)","kind":"report","src":[{"l":"Wikipedia, Cooch Behar","u":"https://en.wikipedia.org/wiki/Cooch_Behar"}]},{"id":"04-124","topic":"culture","ctx":"Tea-belt Adivasi origin","text":"Adivasis from Chotanagpur (Dumka, Hazaribagh, Ranchi, Chaibasa catchments) form a large share of Dooars workers; Nepali and Rajbanshi workers also","kind":"report","src":[{"l":"Wikipedia, Dooars-Terai tea gardens","u":"https://en.wikipedia.org/wiki/Dooars-Terai_tea_gardens"},{"l":"Scroll, Nov 2019","u":"https://scroll.in/article/940717/photo-feature-struggle-and-hope-in-the-tea-gardens-of-the-dooars"}]},{"id":"04-125","topic":"culture","ctx":"Festivals and calendar","text":"Cooch Behar Rash Mela: held on Rash Purnima (full moon of Kartik), usually Nov-Dec, about 15-20 days; DM inaugurates; began under Maharaja Harendra Narayan (1783-1839) per Rajyopakhyan; first at Bhetaguri, then Madan Mohan temple, at the present Rash Mela Ground since 1912; organised by Cooch Behar Municipality and Debuttor Trust Board; cancelled in 2020.","kind":"report","src":[{"l":"Wikipedia, Cooch Behar Rash Mela (orientation)","u":"https://en.wikipedia.org/wiki/Cooch_Behar_Rash_Mela"}]},{"id":"04-126","topic":"culture","ctx":"Festivals and calendar","text":"2024 dates listed on district site: 15/11/2024 to 30/11/2024","kind":"official","src":[{"l":"coochbehar.gov.in","u":"https://coochbehar.gov.in/?p=26557"}]},{"id":"04-127","topic":"culture","ctx":"Festivals and calendar","text":"What visitors see: Madan Mohan temple rituals, Rash Chakra (bamboo and paper structure, built by a Muslim artisan family, seen as symbol of communal harmony), kirtan and jatra at night, rides, handicraft and book stalls, traders from Bangladesh, Nepal, Bhutan","kind":"report","src":[{"l":"Wikipedia, Cooch Behar Rash Mela","u":"https://en.wikipedia.org/wiki/Cooch_Behar_Rash_Mela"},{"l":"Wikipedia, Cooch Behar","u":"https://en.wikipedia.org/wiki/Cooch_Behar"}]},{"id":"04-128","topic":"culture","ctx":"Festivals and calendar","text":"Madan Mohan Temple built by Maharaja Nripendra Narayan 1885-1889; sources differ on idol installation year (one gives 1893)","kind":"official","src":[{"l":"coochbehar.gov.in","u":"https://coochbehar.gov.in/?p=26557"},{"l":"1001things.org","u":"https://1001things.org/?p=10486"}]},{"id":"04-129","topic":"culture","ctx":"Festivals and calendar","text":"World Dooars Utsav, Alipurduar Parade Ground: began about two decades ago for tourism; not held 2020-21; 18th edition 28 Dec 2023 to 7 Jan 2024; later edition ran 12 days to 10 Jan; the 19th reportedly drew about 10 lakh people (organiser claim); features performers from tribal communities and stalls from Nepal and Bhutan","kind":"report","src":[{"l":"Millennium Post (18th edition)","u":"https://www.millenniumpost.in/bengal/18th-world-dooars-utsav-inaugurated-in-alipurduar-to-continue-till-jan-7-545959"},{"l":"Millennium Post (concluded)","u":"https://www.millenniumpost.in/bengal/dooars-utsav-concludes-with-record-participation-enthusiasm-594492"}]},{"id":"04-130","topic":"culture","ctx":"Festivals and calendar","text":"Tihar: Deusi and Bhailo songs are sung house to house in Tihar by Nepali-speaking communities in Darjeeling, Sikkim, Assam; Bhai Tika is day five; Gorubathan (Kalimpong hills, next to the Dooars) Maruni troupe sings Deusi at Sombarey market on second Monday of Bhai Tika","kind":"report","src":[{"l":"Wikipedia, Bhailo","u":"https://www.wikipedia.com/wiki/Bhailo"},{"l":"Kalimpong Online News, Nov 2024","u":"https://kalimpongonlinenews.blogspot.com/2024/11/gorubathan-concludes-tihar-with-unique.html"}]},{"id":"04-131","topic":"culture","ctx":"Festivals and calendar","text":"Bodo Durga Puja in Kalchini: see section 1","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/bodo-community-celebrates-55-yrs-of-unique-puja-tradition-581965"}]},{"id":"04-132","topic":"culture","ctx":"Festivals and calendar","text":"Bodo Bwisagu is new-year festival (mid-April, Assam source)","kind":"official","src":[{"l":"Assam Tourism","u":"https://assamtourism.gov.in/festival-month.php"}]},{"id":"04-133","topic":"culture","ctx":"Festivals and calendar","text":"Date variability: Rash Mela and Tihar follow lunar calendars (change yearly); Dooars Utsav dates are set by organisers each year.","kind":"report","src":[]},{"id":"04-134","topic":"culture","ctx":"Music and dance","text":"Bhawaiya: folk music of northern Bengal (Rangpur, Cooch Behar, Goalpara), sung in Rajbanshi/Kamtapuri; central themes love and separation (biraha); melody generally within the middle octave; Abbasuddin Ahmed, born Balarampur, Tufanganj, Cooch Behar, popularised it on records; etymology disputed","kind":"report","src":[{"l":"Wikipedia, Bhawaiya","u":"https://en.wikipedia.org/wiki/Bhawaiya"},{"l":"The Wire","u":"https://thewire.in/culture/folk-pioneer-abbasuddin-ahmeds-songs-still-reshape-bengals-borderscape"}]},{"id":"04-135","topic":"culture","ctx":"Music and dance","text":"Abbasuddin's dates: 27 Oct 1901 to 30 Dec 1959 in one source; others vary","kind":"report","src":[{"l":"Wikipedia, Abbasuddin Ahmed","u":"https://en.wikipedia.org/wiki/Abbasuddin_Ahmed"}]},{"id":"04-136","topic":"culture","ctx":"Music and dance","text":"Deusi-Bhailo and Maruni dance (linked to Kali worship, Dashain full moon through Tihar) in Gorubathan","kind":"report","src":[]},{"id":"04-137","topic":"culture","ctx":"Music and dance","text":"Rabha festivals use flute, singa and karra instruments","kind":"report","src":[{"l":"Indianetzone","u":"https://www.indianetzone.com/10/rabha_tribe.htm"}]},{"id":"04-138","topic":"culture","ctx":"Food","text":"Rajbanshi staples: rice, river fish, foraged greens, bamboo shoot, dried fish (sukati); key dishes Fokdoi, Pata Khaoa, Pyalka, Sidol, Sukati. Sidol: fermented paste of small dried fish, arum stems and spices shaped into dried cakes","kind":"report","src":[{"l":"Maverick Bird","u":"https://maverickbird.com/india/east/west-bengal/darjeeling-local-market-and-the-lesser-known-rajbanshi-cuisine-of-bengal/"},{"l":"Slurrp","u":"https://www.slurrp.com/article/from-borolir-jhaal-to-rai-saag-discovering-authentic-traditional-foods-of-north-bengal-1764185938444"}]},{"id":"04-139","topic":"culture","ctx":"Food","text":"Toto Eu: millet-based mild alcoholic drink fermented with starter \"Moaa\" (rice powder, sometimes medicinal plants); accounts of ingredients vary (marua, rice, maize, kauni); used in rituals and social gatherings; peer-reviewed study finds it safe and antioxidant-active","kind":"report","src":[{"l":"Springer, Journal of Ethnic Foods 2021","u":"https://link.springer.com/10.1186/s42779-021-00093-5"}]},{"id":"04-140","topic":"culture","ctx":"Food","text":"Gundruk, a fermented leafy green, connects hill and Rajbanshi forage cuisines (secondary)","kind":"report","src":[{"l":"Maverick Bird","u":"https://maverickbird.com/india/east/west-bengal/darjeeling-local-market-and-the-lesser-known-rajbanshi-cuisine-of-bengal/"}]},{"id":"04-141","topic":"culture","ctx":"Crafts and textiles","text":"GI application \"Cooch Behar Sitalpati\" (no. 901) filed 1 June 2022 by West Bengal Khadi and Village Industries Board, Class 20, status \"Advertised\" (cached registry entry; check current)","kind":"official","src":[{"l":"IP India GI registry","u":"https://search.ipindia.gov.in/GIRPublicSearch/Application/Details/901"},{"l":"IP India","u":"https://search.ipindia.gov.in/GIRPublicSearch/Application/Details/442"}]},{"id":"04-142","topic":"culture","ctx":"Crafts and textiles","text":"About 40,000 people depend on Sitalpati in Cooch Behar (Millennium Post, 28 May 2023); other estimates 30,000 and 3,807 artisans (sources differ); Dhaluabari, Block No. 1, biggest concentration; DM Pawan Kadian expected GI \"within months\"","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/weaving-heritage-cooch-behars-shitalpati-in-race-for-gi-tag-520189"}]},{"id":"04-143","topic":"culture","ctx":"Crafts and textiles","text":"Raw material is mutra cane; weaving centres include Sagareswar, Ghugumari, Pashnadanga","kind":"report","src":[{"l":"Millennium Post, state starts GI process","u":"https://www.millenniumpost.in/kolkata/state-starts-process-to-seek-gi-registration-for-sitalpati-mats-of-cooch-behar-454948"}]},{"id":"04-144","topic":"culture","ctx":"Crafts and textiles","text":"A claim that UNESCO has recognised Sitalpati as intangible cultural heritage appeared in a summary; I could not verify it and it is not in UNESCO lists I read. Treat as unverified: do not publish.","kind":"report","src":[]},{"id":"04-145","topic":"culture","ctx":"Tea-garden life","text":"First Terai plantation 1862 (Champta); 13 Dooars-Terai plantations by 1876; first Dooars garden at Gazalduba","kind":"report","src":[{"l":"Wikipedia, Dooars-Terai tea gardens","u":"https://en.wikipedia.org/wiki/Dooars-Terai_tea_gardens"}]},{"id":"04-146","topic":"culture","ctx":"Tea-garden life","text":"154 of 283 north Bengal gardens are in the Dooars, employing about 3.5 lakh workers (figures vary by source); region produces about 226 million kg, a quarter of India's crop","kind":"report","src":[]},{"id":"04-147","topic":"culture","ctx":"Tea-garden life","text":"4.5 lakh workers across Hills, Dooars, Terai, about 2.62 lakh permanent; gardens shifted to casual workers to avoid Plantation Labour Act provisions (Scroll, Nov 2019)","kind":"report","src":[{"l":"Scroll","u":"https://scroll.in/article/940717/photo-feature-struggle-and-hope-in-the-tea-gardens-of-the-dooars"}]},{"id":"04-148","topic":"culture","ctx":"Tea-garden life","text":"Interim minimum daily wage Rs 176 in 2019","kind":"report","src":[{"l":"Scroll","u":"https://scroll.in/article/940717/photo-feature-struggle-and-hope-in-the-tea-gardens-of-the-dooars"}]},{"id":"04-149","topic":"culture","ctx":"Tea-garden life","text":"17 Dooars gardens closed 2002-2007; at least 1,200 deaths reported in tea areas (press estimate); Dheklapara closed 2002 with about 600 workers staying; a figure of 56 starvation deaths at Dheklapara comes from a secondary citation and needs checking","kind":"report","src":[{"l":"Scroll","u":"https://scroll.in/article/940717/photo-feature-struggle-and-hope-in-the-tea-gardens-of-the-dooars"},{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Dooars-Terai_tea_gardens"}]},{"id":"04-150","topic":"culture","ctx":"Tea-garden life","text":"Closure-linked trafficking and out-migration reported (Sikkim, Bhutan, Delhi, Kerala)","kind":"report","src":[{"l":"Scroll","u":"https://scroll.in/article/940717/photo-feature-struggle-and-hope-in-the-tea-gardens-of-the-dooars"}]},{"id":"04-151","topic":"culture","ctx":"Tea-garden life","text":"Sonali garden cooperative run by workers since 1974","kind":"report","src":[]},{"id":"04-152","topic":"culture","ctx":"Tea-garden life","text":"Pay: tripartite wage negotiations; part payment in kind (rations, fuel, housing, medical)","kind":"report","src":[{"l":"NBU repository study","u":"https://ir.nbu.ac.in/bitstreams/42ac6abb-948d-4514-a1f3-d3ce38faacc0/download"}]},{"id":"04-153","topic":"culture","ctx":"Tea-garden life","text":"Rangamati Tea Estate Cemetery holds European planters' graves","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Dooars-Terai_tea_gardens"}]},{"id":"04-154","topic":"culture","ctx":"Responsible-travel and cultural sensitivity","text":"Totos are a very small community under pressure on language, land and identity; they asked that village land be reserved and that Toto be taught in school","kind":"report","src":[{"l":"The Federal","u":"https://thefederal.com/the-eighth-column/a-small-tribes-struggle-to-balance-development-and-cultural-identity"}]},{"id":"04-155","topic":"culture","ctx":"Responsible-travel and cultural sensitivity","text":"Homestay-based tourism exists in Totopara via state support","kind":"report","src":[]},{"id":"04-156","topic":"culture","ctx":"Responsible-travel and cultural sensitivity","text":"Toto religion involves animal sacrifice and Eu offerings, so ritual sites and gatherings are not performances","kind":"report","src":[{"l":"Wikipedia, Toto people","u":"https://en.wikipedia.org/wiki/Toto_people"}]},{"id":"04-157","topic":"culture","ctx":"Responsible-travel and cultural sensitivity","text":"Rash Mela welcomes all faiths (Wikipedia statement)","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Cooch_Behar_Rash_Mela"}]},{"id":"05-158","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"Kanchan Kanya Express 13149 (Sealdah to Alipurduar) and 13150 (return): sources conflict on times. 13149 departs Sealdah about 20:30-20:35, arrives Alipurduar Jn about 12:10-12:35 next day; 13150 departs Alipurduar about 15:15-16:00, arrives Sealdah about 08:15-08:20; journey roughly 15.5-16 hours; several sites say daily.","kind":"report","src":[{"l":"indiantrain.in 13149","u":"https://www.indiantrain.in/train-time-table/13149"},{"l":"totaltraininfo 13149","u":"https://www.totaltraininfo.com/train/13149/schedule"}]},{"id":"05-159","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"Vande Bharat Express 22302 (NJP to Howrah) listed departing NJP 15:00, running except Wednesday, about 560 km in 7h30 (aggregator listing, year not stated).","kind":"report","src":[{"l":"railmitra / erail listings via search","u":"https://www.railmitra.com/trains/new-jalpaiguri-to-kolkata"}]},{"id":"05-160","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"Sealdah-NJP Humsafar 13116 (NJP side to Sealdah) takes about 11h40; aggregators count 33-37 trains per week/total between Kolkata and NJP.","kind":"report","src":[{"l":"erail.in Sealdah-NJP","u":"https://erail.in/trains-between-stations/sealdah-SDAH/new-jalpaiguri-NJP"}]},{"id":"05-161","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"17 January 2026: PM Modi flagged off India's first Vande Bharat Sleeper (Howrah-Guwahati/Kamakhya) from Malda; New Cooch Behar-Bamanhat and New Cooch Behar-Boxirhat lines were electrified/dedicated; four Amrit Bharat Express trains flagged off, two from Alipurduar (to Bengaluru SMVT and Mumbai Panvel).","kind":"report","src":[{"l":"The Statesman","u":"https://www.thestatesman.com/india/india-gets-its-first-vande-bharat-sleeper-pm-modi-flags-off-howrah-guwahati-train-from-west-bengals-malda-1503542073.html/amp"},{"l":"The Week, 17 Jan 2026","u":"https://www.theweek.in/news/biz-tech/2026/01/17/west-bengal-pm-modi-flags-off-4-amrit-bharat-express-trains-amid-rs-3250-crore-road-rail-infra-package-announcement.html"}]},{"id":"05-162","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"A New Jalpaiguri-Alipurduar Tourist Special/Express exists as a Wikipedia entry; current running status not confirmed.","kind":"report","src":[{"l":"Wikipedia","u":"https://www.Wikipedia.org/wiki/New_Jalpaiguri%E2%80%93Alipurduar_Tourist_Special"}]},{"id":"05-163","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"Jaldhaka river washed away a culvert on the Altagram-Betgara rail line in an undated flood episode, disrupting North Bengal-Northeast rail links.","kind":"report","src":[{"l":"Outlook Business","u":"https://www.outlookbusiness.com/planet/climate/darjeeling-landslides-bhutan-dam-overflow-flood-alert"}]},{"id":"05-164","topic":"transport","ctx":"Air: Bagdogra, Cooch Behar, Hasimara, Paro","text":"Bagdogra: single terminal, domestic flights from Delhi, Kolkata, Mumbai, Bengaluru; Delhi-Bagdogra about 2h15; Kolkata-Bagdogra quoted 1h10 or about 1h40 (sources differ). Fare snapshots: Delhi-Bagdogra from about Rs 5,000; Bagdogra-Kolkata from Rs 6,849 (dated snapshots). Prepaid taxi counters at airport and NJP.","kind":"report","src":[{"l":"HappyFares Bagdogra guide 2026","u":"https://happyfares.in/blog/?p=2979"},{"l":"Air India","u":"https://www.airindia.com/en/book-flights/bagdogra-to-kolkata-flights"}]},{"id":"05-165","topic":"transport","ctx":"Air: Bagdogra, Cooch Behar, Hasimara, Paro","text":"Cooch Behar airport: Millennium Post reported Kolkata flight to stop from Feb 2026 (operator not renewing contract), later reported weekly flights to continue from Feb 12, and another report says suspended. Aggregators list IndiaOne Air as sole operator (one says 7 weekly as of May 2026). Wikipedia cites 4,297 passengers April 2025-March 2026, down 21.6%.","kind":"report","src":[{"l":"Millennium Post (stop)","u":"https://www.millenniumpost.in/bengal/cooch-beharkolkata-flight-to-stop-from-feb-2026-sparks-row-637989"},{"l":"Millennium Post (weekly)","u":"https://www.millenniumpost.in/bengal/cooch-behar-to-kolkata-flights-to-continue-weekly-from-feb-12-647121"}]},{"id":"05-166","topic":"transport","ctx":"Air: Bagdogra, Cooch Behar, Hasimara, Paro","text":"Bagdogra to Phuentsholing about 165 km, 4-5 hours via Siliguri and Hasimara.","kind":"report","src":[{"l":"littlebhutan.com, page checked 24 Aug 2026","u":"https://littlebhutan.com/travel-guide/entering-bhutan-by-road/"}]},{"id":"05-167","topic":"transport","ctx":"Road and bus","text":"P.C. Mittal Memorial Bus Terminus (Sevoke Road, Siliguri, \"Dooars Bus Stand\") lists routes to Lataguri and Alipurduar.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/P._C._Mittal_Memorial_Bus_Terminus"}]},{"id":"05-168","topic":"transport","ctx":"Road and bus","text":"NBSTC direct buses Jayanti-Alipurduar-Siliguri launched (about 5 am from Jayanti to Siliguri); article date not shown.","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/direct-bus-service-from-jayanti-to-alipurduar-starts-520296"}]},{"id":"05-169","topic":"transport","ctx":"Road and bus","text":"A daily tourist bus from Jaldapara Tourist Lodge/Alipurduar at 7 am stops at Phuentsholing, Jayanti, Rajabhatkhawa, Sikiajhora.","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/new-tourist-bus-service-launched-in-alipurduar-582312"}]},{"id":"05-170","topic":"transport","ctx":"Road and bus","text":"Itinerary distances: Hasimara/NJP to Jaldapara 125.9 km via NH17; Jayanti to Lataguri 132.3 km.","kind":"operator","src":[{"l":"north-bengal.com","u":"https://www.north-bengal.com/buxa-and-jaldapara-tour-dooars-holidays.php"}]},{"id":"05-171","topic":"transport","ctx":"Road and bus","text":"Disruptions: 25 June 2026 massive NH10 landslide near Siliguri cut Sikkim/Kalimpong links; Red Alert for lower Teesta; Teesta, Torsa, Jaldhaka, Raidak, Mahananda rising.","kind":"report","src":[{"l":"ETV Bharat, 25 Jun 2026","u":"https://www.etvbharat.com/en/state/massive-landslide-on-nh-10-in-siliguri-cuts-sikkim-kalimpong-link-enn26062504678"},{"l":"Outlook India","u":"https://www.outlookindia.com/national/west-bengal-floods-death-toll-rises-to-28-as-darjeeling-devastated-by-landslides"}]},{"id":"05-172","topic":"transport","ctx":"Road and bus","text":"Jaigaon border congestion: January 2026 New Year surge caused long queues.","kind":"report","src":[{"l":"Kalimpong Online News, Jan 2026","u":"https://kalimpongonlinenews.blogspot.com/2026/01/tourist-rush-causes-long-queues-at.html"}]},{"id":"05-173","topic":"transport","ctx":"Local transport and safaris","text":"UNI India (Oct 2026): Jaldapara safari booking going online, 48 elephant-ride seats open for advance online booking.","kind":"report","src":[{"l":"UNI India","u":"https://www.uniindia.com/east-india/tourism-wb-jaldapara-durga-puja/214066"}]},{"id":"05-174","topic":"transport","ctx":"Local transport and safaris","text":"Older guides: jeep safari Rs 450 per person or jeep Rs 1,750 for 6; one review Rs 480 for 4 (afternoon jeep), Rs 4,080 for 4 (elephant); park entry Rs 100 Indian / Rs 200 foreign; elephant slots 5:30-6:30 and 6:30-7:30; park open 16 Sep-14 Jun. Bookings via WBTDC Madarihat or WBFDA.","kind":"operator","src":[{"l":"Pickyourtrail","u":"https://pickyourtrail.com/blog/jaldapara-national-park"},{"l":"north-bengal.com Jaldapara","u":"https://north-bengal.com/jaldapara-dooars.php"}]},{"id":"05-175","topic":"transport","ctx":"Bhutan border: Jaigaon-Phuentsholing, permits, SDF","text":"Indians: valid passport (6 months) or original Voter ID; photos; minors without passport need birth certificate; SDF INR 1,200 per day; entry permit from Phuentsholing (+975-05-252383/254639), Gelephu, Samdrup Jongkhar, Samtse offices or Paro airport; carry-cash limits Rs 25,000 (notes up to Rs 500). Page last updated 5 Nov 2026.","kind":"official","src":[{"l":"Embassy of India Thimphu","u":"https://indembthimphu.gov.in/pages/NDA5"}]},{"id":"05-176","topic":"transport","ctx":"Bhutan border: Jaigaon-Phuentsholing, permits, SDF","text":"Pedestrian terminal open 24 hours; vehicle gate about 6am-11pm; Bhutanese immigration 24h; Indian immigration office at Jaigaon on office hours (accounts conflict). Private vehicles Nu 4,500 per car per day; route permits no longer required for tourists within Bhutan (per this operator).","kind":"report","src":[{"l":"littlebhutan.com, checked 24 Aug 2026","u":"https://littlebhutan.com/travel-guide/entering-bhutan-by-road/"}]},{"id":"05-177","topic":"transport","ctx":"Bhutan border: Jaigaon-Phuentsholing, permits, SDF","text":"Border-town day-visit SDF waiver (under 24 hours to Samtse, Phuentsholing, Gelephu, Samdrup Jongkhar), reportedly from 2 June 2026 to Aug 2027, from travel sites only.","kind":"operator","src":[{"l":"Holidify","u":"https://holidify.com/pages/bhutan-visa-for-indians-6749.html"},{"l":"happyfares","u":"https://www.happyfares.in/blog/?p=3417"}]},{"id":"05-178","topic":"transport","ctx":"Bhutan border: Jaigaon-Phuentsholing, permits, SDF","text":"Conflict: stylecraze claims free entry ended July 2026; this contradicts other sources (fee has applied earlier) and is treated as unreliable. Another source states a $15 equivalent; the official Embassy figure is INR 1,200.","kind":"report","src":[{"l":"stylecraze","u":"https://www.stylecraze.com/trending/bhutan-ended-free-entry-for-indians-in-july"}]},{"id":"05-179","topic":"transport","ctx":"Travel from Kolkata: options","text":"See Rail, Air, Road sections above (Kanchan Kanya about 20:30 departure, arriving about 12:10-12:35; Vande Bharat about 7.5h to NJP; flight 1h10-1h40; Bagdogra to Phuentsholing 4-5h).","kind":"report","src":[]},{"id":"06-180","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"State-wide: a Bengal tourism official said over 2,000 homestays are registered with the department; Kalimpong 974, Darjeeling about 200; no separate Alipurduar/Jalpaiguri count. Article page header shows Jan 2025 but underlying report date uncertain [NEWS, date uncertain]","kind":"report","src":[{"l":"Telegraph (TTEF mirror)","u":"https://obeta.ttef.in/west-bengal/bengal-tag-cash-for-alipurduar-homestay-accommodations/cid/1877520"}]},{"id":"06-181","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Alipurduar homestay owners began receiving state registration certificates in 2022 [NEWS, 2022]","kind":"report","src":[{"l":"Telegraph via Kalimpong Online News","u":"https://kalimpongonlinenews.blogspot.com/2022/08/bengal-tag-cash-for-alipurduar-homestay.html"}]},{"id":"06-182","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Telegraph feature: \"hundreds of homestays have mushroomed across north Bengal, from the Darjeeling hills to the Dooars\" [NEWS, undated]","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/a-look-at-north-bengals-emerging-tourist-favourite/cid/1729317"}]},{"id":"06-183","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Private hotels are concentrated at Lataguri; state resorts (WBFDC/WBTDCL) at Murti [OPERATOR/guide]","kind":"operator","src":[{"l":"darjeeling-tourism.com","u":"https://www.darjeeling-tourism.com/darj_000209.htm"}]},{"id":"06-184","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Gorumara Wildlife Division (Forest Dept) reopened Dhupjhora Elephant Camp, Kalipur and Mouchuki eco-cottages from 1 Dec 2024 after closure since COVID; double-bed suites at Kalipur and Mouchuki cut from Rs 2,200 to Rs 1,200/night; six Dhupjhora cottages renovated; solar-powered; reference to a fire at Hollong Forest Bungalow, Jaldapara [NEWS, 30 Nov 2024]","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/gorumara-eco-cottages-to-reopen-with-lower-tariffs-from-dec-1-588763"}]},{"id":"06-185","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Hollong Tourist Lodge (Jaldapara) is listed as WBTDCL, bookable via wbtdcl.wbtourismgov.in; WBFDC lodges (e.g., Banani Lodge, Murti) bookable up to 90 days ahead via Salt Lake (Kolkata) office or WBFDC online portal with account [OPERATOR/blog guides, undated]","kind":"official","src":[{"l":"swarnabdutta.com","u":"https://www.swarnabdutta.com/how-to-book-wbfdc-resorts-properties-online"},{"l":"northbengaltourism.com Hollong","u":"https://northbengaltourism.com/hotel-booking/hollong-tourist-lodge/0/"}]},{"id":"06-186","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Season: October to April is best; Dec-Feb peak; June-Sept monsoon, most forest areas closed [OPERATOR, Mar 2026]","kind":"operator","src":[{"l":"Resort Trimurti blog","u":"https://www.resorttrimurti.com/blog/dooars-jungle-safari-price-booking-best-time-complete-travel-guide"}]},{"id":"06-187","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Tea-estate luxury comparators (Darjeeling, not Dooars): Glenburn Rs 28,000-45,000/night double plus taxes; Taj Chia Kutir Rs 20,000-80,000/day; tea tourism packages from Rs 10,000 pp for 2N/3D [NEWS, 28 May 2023]","kind":"report","src":[{"l":"ThePrint","u":"https://www.theprint.in/ground-reports/darjeeling-tea-estates-are-now-luxury-tourism-hotspots-taj-hotels-offering-leaf-picking-spa/1598651"}]},{"id":"06-188","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Telegraph feature example of north Bengal homestay pricing: Kalimpong Rs 1,000 per person per day with meals [NEWS, undated, Kalimpong not Dooars]","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/a-look-at-north-bengals-emerging-tourist-favourite/cid/1729317"}]},{"id":"06-189","topic":"stay_tea","ctx":"Booking channels, commissions, associations, agent models","text":"2018-19 disputes: Mysuru association (400 members) wanted commission cut to 15% pay-at-hotel / 18% prepaid; FHRAI VP said OTAs normally 12-15% but MakeMyTrip/Goibibo charged 20-40%; Gujarat association set 18% cap; FHRAI put MakeMyTrip and Goibibo on notice Dec 2018 [NEWS, 2018-19]","kind":"report","src":[{"l":"Asian Age","u":"https://www.asianage.com/business/companies/200219/hotels-travel-service-providers-at-war.html"},{"l":"YourStory","u":"https://yourstory.com/2018/12/hotels-association-makemytrip-goibibo-notice"}]},{"id":"06-190","topic":"stay_tea","ctx":"Booking channels, commissions, associations, agent models","text":"Booking.com complaints from hoteliers (Spain association, 2024) [NEWS]","kind":"report","src":[{"l":"10minhotel","u":"https://en.10minhotel.com/2024/07/18/hoteliers-accuse-booking-com-of-unfair-business-practices"}]},{"id":"06-191","topic":"stay_tea","ctx":"Booking channels, commissions, associations, agent models","text":"A north Bengal online platform launched travel shows to promote homestays (visibility via digital channels) [NEWS, c.2024-25]","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/north-bengal-based-online-platform-launches-three-new-travel-shows-to-boost-homestays/cid/2022062"}]},{"id":"06-192","topic":"stay_tea","ctx":"Booking channels, commissions, associations, agent models","text":"State homestay portal reported to help tourists [NEWS, c.2022]","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/portal-on-homestays-to-help-tourists/cid/1875173"}]},{"id":"06-193","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"210 gardens across Alipurduar and Jalpaiguri, only 45 fully/partially operating [OPERATOR/NGO blog, undated]","kind":"report","src":[{"l":"CASA","u":"https://casa-india.org/blog/?p=5523"}]},{"id":"06-194","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"Jalpaiguri: 92 large estates; Jalpaiguri 20,575 small tea growers, Alipurduar 458, Cooch Behar 3,530 (Tea Board assessment table, undated)","kind":"official","src":[{"l":"Tea Board PDF","u":"https://teaboard.gov.in/pdf/SmallTea_Growers_in_North_Bengal_Bihar.pdf"},{"l":"Outlook","u":"https://www.outlookindia.com/csr/csr-2019-03/tea-board"}]},{"id":"06-195","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"Closures: 17 gardens shut 2002-07; reports of up to 32 closed since Feb 2015 affecting about 60,000 people [NEWS]","kind":"report","src":[{"l":"Scroll","u":"https://scroll.in/article/940717/photo-feature-struggle-and-hope-in-the-tea-gardens-of-the%20dooars"},{"l":"The Week","u":"https://www.theweek.in/theweek/statescan/dooars-region-starvation-deaths.html"}]},{"id":"06-196","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"Recent: three gardens (Chamurchi, Redbank, Surendranagar) abruptly closed (date not visible); six gardens closed/abandoned over bonus disputes, about 7,000 jobless before Durga Puja (year not confirmed) [NEWS]","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/closure-of-3-dooars-tea-gardens-leaves-over-2k-workers-in-crisis-627132"},{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/cash-woes-in-tea-bonus-rows-dooars-tea-garden-shutdowns-leave-7000-jobless-before-durga-puja/cid/1973623"}]},{"id":"06-197","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"2025 floods damaged 30+ gardens in Alipurduar/Jalpaiguri, losses above Rs 100 crore [NEWS, 2025]","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/north-bengal-tea-industry-in-crisis-small-growers-see-slight-relief-632805"}]},{"id":"06-198","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"Tea Tourism and Allied Business Policy 2019: 15% of grant area, max 150 acres, only unused land","kind":"official","src":[{"l":"WB Industries PDF","u":"https://wbindustries.gov.in/policies-schemes/Tea_Tourism_and_Allied_Business_Policy_2019.pdf"},{"l":"WBXpress","u":"https://wbxpress.com/tea-tourism-allied-business-policy-2019/"}]},{"id":"06-199","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"2025: ceiling raised to 30%; Feb 2025 CM said beyond 15% evaluated case-by-case, with no pending PF/gratuity/wage dues; unions and opposition objected [NEWS, 2025]","kind":"report","src":[{"l":"ETV Bharat","u":"https://etvbharat.com/en/!state/no-compromise-on-tea-cultivation-amidst-tourism-approvals-bengal-cm-mamata-enn25022505612"},{"l":"Statesman","u":"https://www.thestatesman.com/bengal/tea-turmoil-state-govt-amends-tea-tourism-policy-in-response-to-protests-brewing-over-land-rights-1503409973.html"}]},{"id":"06-200","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"15 June 2026: Tourism Minister Shankar Ghosh said tea tourism must not harm tea industry; clear tourism policy intended within six months [NEWS, Jun 2026]","kind":"report","src":[{"l":"UNI","u":"https://test.uniindia.com/tourism-growth-must-not-come-at-the-cost-of-tea-industry-bengal-minister-shankar-ghosh/east/news/3877802.html"}]},{"id":"06-201","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"2023: 16 private proposals for tea-garden tourism in Darjeeling, Terai and Dooars, Rs 1,400 crore, 4,500+ jobs (Telegraph via ThePrint)","kind":"report","src":[{"l":"ThePrint","u":"https://www.theprint.in/ground-reports/darjeeling-tea-estates-are-now-luxury-tourism-hotspots-taj-hotels-offering-leaf-picking-spa/1598651"}]},{"id":"06-202","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"Examples: Octavius Tea Resorts: Sylee Bungalow (Sylee Tea Estate) and Nya Sylee Bungalow (near Nagrakata); tea walks, tasting; room counts/prices not stated [OPERATOR, 21 Aug 2026]","kind":"operator","src":[{"l":"Octavius blog","u":"https://octaviustea.digitalpress.blog/heritage-tea-estate-in-dooars/"},{"l":"Windhorse","u":"https://www.windhorsetours.com/hotels/zurantee-heritage-bungalow"}]},{"id":"06-203","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"Green leaf price about Rs 12-13/kg vs cost Rs 18.52 (small growers) [NEWS]","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/intense-monsoonal-downpour-in-sub-himalayan-bengal-poses-problems-for-small-tea-sector/cid/1953876"}]},{"id":"06-204","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"14 Oct 2026: online safari booking commenced at Jaldapara up to one month ahead; 912 daily seats over five routes (Salkumar, Madarihat, Lankapara, Chilapata, Kodalbasti); 48 elephant seats [NEWS]","kind":"report","src":[{"l":"UNI","u":"https://www.uniindia.com/east-india/tourism-wb-jaldapara-durga-puja/214066"}]},{"id":"06-205","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"Earlier report: online booking reintroduced for elephant safaris only, car safaris offline (undated)","kind":"report","src":[{"l":"News Arena","u":"https://newsarenaindia.com/states/dooars-elephant-safaris-return-ahead-of-durga-puja/56423"}]},{"id":"06-206","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"Fees (2026 operator estimate, not official; page internally inconsistent): Gorumara/Chapramari jeep Rs 2,500-4,000; Jaldapara jeep Rs 3,500-4,500; elephant Rs 1,000-1,500 pp; permit Rs 200-400 pp; guide Rs 300-500; slots 6-8, 8:30-10:30, 14:30-16:30, elephant 5:30-6:30; 4-6 per jeep","kind":"operator","src":[{"l":"Resort Trimurti, Mar 2026","u":"https://www.resorttrimurti.com/blog/dooars-jungle-safari-price-booking-best-time-complete-travel-guide"},{"l":"tourtravelworld","u":"https://www.tourtravelworld.com/packages/jalpaiguri_jeep-safari-holidays.htm"}]},{"id":"06-207","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"Buxa: villagers of 18 villages agitating over conservation/livelihood; Association for Conservation & Tourism wrote to CM Suvendu Adhikari on 22 Oct 2026 to resume tourism [NEWS, 23 Oct 2026]","kind":"report","src":[{"l":"UNI","u":"https://www.uniindia.com/east-india/tourism-wb-buxa-crisis/223086"},{"l":"UNI 7 Oct 2026","u":"https://www.uniindia.com/east-india/agitation-wb-buxa-protest/205766"}]},{"id":"06-208","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"Raimatang homestay owner: lost 90% of business in six years; only 20% of core zone can be opened for tourism; Jayanti residents rely on homestays, safaris, treks [NEWS]","kind":"report","src":[{"l":"Village Square","u":"https://villagesquare.in/north-bengal-tiger-reserve-without-safari/"}]},{"id":"06-209","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"Revenue share with communities mentioned by a forest official (2023)","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/vigilantes-get-part-of-buxa-cash/cid/1930968"}]},{"id":"06-210","topic":"stay_tea","ctx":"Operators and package prices","text":"3N/4D Dooars: Rs 6,000-6,200 pp budget; Rs 9,200-9,625 pp mid; Rs 15,599 pp twin sharing with 3-star Lataguri and WBTDC Jaldapara; lowest advertised Rs 5,300; safari/entry/guide often excluded","kind":"operator","src":[{"l":"tourtravelworld","u":"https://www.tourtravelworld.com/packages/green-dooars-jaldapara-lataguri3n4d-tour-241175.html"},{"l":"Musafir","u":"https://in.musafir.com/Holidays/Beautiful_Dooars.aspx"}]},{"id":"06-211","topic":"stay_tea","ctx":"Problems reported","text":"Buxa tourism shutdown/agitation, Oct 2026 (see section 4); Raimatang decline; offline-only car safari booking historically; tea-garden worker dues/closures; 2025 floods","kind":"report","src":[]},{"id":"06-212","topic":"stay_tea","ctx":"Benchmarks","text":"Kerala RT Mission: RT unit revenue Rs 23.07 crore in 2019-20 (from Rs 4.98 crore prior; est.); about 17,000 registered units employing 100,000 (2020, secondary); Rs 6.64 crore projects approved 2024-25; reconfigured as KRTMS in 2023","kind":"operator","src":[{"l":"TravelBizMonitor","u":"https://travelbizmonitor.com/?p=39187"},{"l":"Travel Trends Today","u":"https://www.traveltrendstoday.in/kerala-launches-responsible-tourism-mission"}]},{"id":"06-213","topic":"stay_tea","ctx":"Benchmarks","text":"Darjeeling/Kalimpong: state homestay cash aid reported (Kalimpong)","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/mamata-banerjee-government-allots-cash-aid-for-kalimpong-homestays/cid/1834911"}]},{"id":"08-214","topic":"news","ctx":"Floods, landslides, disasters and recovery","text":"Floods on 5 Oct 2025 submerged parts of Jaldapara (Torsa and Sishmara blamed); elephant and jeep safaris suspended; several wooden bridges on safari routes damaged; forest department repaired them in about two weeks; full safaris and Madarihat gate resumed Monday 20 Oct 2025.","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/jaldapara-jumbo-jeep-safaris-set-to-resume-631890"}]},{"id":"08-215","topic":"news","ctx":"Floods, landslides, disasters and recovery","text":"Hulong River wooden bridge (Jaldapara) collapsed; a new wooden bridge was built quickly and opened before the CM's visit; it revived tourism around Hulong Bungalow; road repairs still under way near Jaldapara (updated 13 Oct 2025)","kind":"report","src":[{"l":"News Arena","u":"https://newsarenaindia.com/states/north-bengal-returns-to-normalcy-after-floods-and-landslides/59260"}]},{"id":"08-216","topic":"news","ctx":"Floods, landslides, disasters and recovery","text":"Jaldhaka washed away a culvert on the Altagram-Betgara rail line, cutting North Bengal-Northeast rail links; NFR built a temporary steel slab bridge in seven days; trains ran at 10 km/h; Mainaguri-route trains rerouted via Mathabhanga and Jalpaiguri Road (13 Oct 2025)","kind":"report","src":[{"l":"News Arena","u":"https://newsarenaindia.com/states/north-bengal-returns-to-normalcy-after-floods-and-landslides/59260"}]},{"id":"08-217","topic":"news","ctx":"Floods, landslides, disasters and recovery","text":"Outlook Traveller (updated 9 Oct 2025): Darjeeling roads reopened after landslides, Sandakphu access restored, Rohini Road under GTA repair; Jaldapara and Gorumara hit hard; at least one rhino, three gaur and a sambar feared dead (note: conflicts with the \"wildlife largely unharmed\" line above, written 10 days later)","kind":"operator","src":[{"l":"Outlook Traveller","u":"https://www.outlooktraveller.com/News/north-bengal-floods-roads-reopen-but-recovery-remains-slow"}]},{"id":"08-218","topic":"news","ctx":"Floods, landslides, disasters and recovery","text":"Puja-season losses estimated at up to Rs 500 crore; Sikkim rain plus Bhutan water and dolomite deposits blamed (29 Dec 2025, trade-news site, estimate unverified)","kind":"operator","src":[{"l":"Travel And Tour World","u":"https://www.travelandtourworld.com/news/article/dooars-winter-tourism-sees-revival-after-devastating-floods-offering-hope-for-a-stronger-2026-season/"}]},{"id":"08-219","topic":"news","ctx":"Floods, landslides, disasters and recovery","text":"Winter 2025-26 recovery: 20 Dec to 10 Jan, accommodation in Jayanti, Jaldapara, Madarihat and Lataguri nearly fully booked; Jaldapara car safaris sold out within minutes on 24-25 Dec; bookings fell after 26 Dec, which stakeholders linked to the Special Intensive Revision (SIR) voter-roll process (29 Dec 2025)","kind":"operator","src":[{"l":"Travel And Tour World","u":"https://www.travelandtourworld.com/news/article/dooars-winter-tourism-sees-revival-after-devastating-floods-offering-hope-for-a-stronger-2026-season/"}]},{"id":"08-220","topic":"news","ctx":"Parks and forests: closures, openings, fees, slots, fire","text":"Jan 2025: forest entry fees waived (announced 22 Jan 2025 per guide); online jeep booking stopped soon after. Fees restored 18 Sep 2026: Rs 200 per person and Rs 480 per vehicle; manual counters in use (Telegraph 17 Sep 2026, via secondary)","kind":"report","src":[{"l":"Offbeatpeak guide, updated 15 Oct 2026","u":"https://offbeatpeak.com/destination/dooars-safari-booking-guide/"},{"l":"Telegraph","u":"https://www.telegraphindia.com/west-bengal/entry-fees-to-forests-to-restart-from-friday-after-18-month-waiver-prnt/cid/2180302"}]},{"id":"08-221","topic":"news","ctx":"Parks and forests: closures, openings, fees, slots, fire","text":"16 Sep 2025: online booking returned for elephant safaris only (Jaldapara, Gorumara); jeep safaris stayed offline","kind":"report","src":[{"l":"Millennium Post, 15 Sep 2025","u":"https://www.millenniumpost.in/bengal/online-booking-for-elephant-safaris-to-resumes-from-today-627451"}]},{"id":"08-222","topic":"news","ctx":"Parks and forests: closures, openings, fees, slots, fire","text":"16 Sep 2026: Gorumara, Chapramari, Jaldapara, Buxa reopened after monsoon closure; Millennium Post (18 Sep 2026) confirms tourism picked up from 16 Sep","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/durga-puja-vacation-rush-strong-tourist-bookings-reported-in-dooars-676407"}]},{"id":"08-223","topic":"news","ctx":"Parks and forests: closures, openings, fees, slots, fire","text":"14 Oct 2026: online safari booking at Jaldapara opened (up to one month ahead); DFO Parveen Kaswan said 912 safari seats daily across five routes (Salkumar, Madarihat, Lankapara, Chilapata, Kodalbasti) plus 48 elephant-ride seats (excerpt only, paywalled)","kind":"report","src":[{"l":"UNI","u":"https://www.uniindia.com/east-india/tourism-wb-jaldapara-durga-puja/214066"}]},{"id":"08-224","topic":"news","ctx":"Parks and forests: closures, openings, fees, slots, fire","text":"2026 annual closure listed as 16 Jun-15 Sep for WBFDC lodges (Chatakpur, Neora Jungle Camp, Mendabari); Jaldapara closed from about 15 Jun 2026","kind":"report","src":[{"l":"Offbeatpeak guide","u":"https://offbeatpeak.com/destination/dooars-safari-booking-guide/"}]},{"id":"08-225","topic":"news","ctx":"Parks and forests: closures, openings, fees, slots, fire","text":"Thursday weekly off at Gorumara and Jaldapara (Darjeeling Tourism, 2022 data; no official 2026 notice)","kind":"report","src":[{"l":"Offbeatpeak guide","u":"https://offbeatpeak.com/destination/dooars-safari-booking-guide/"}]},{"id":"08-226","topic":"news","ctx":"Parks and forests: closures, openings, fees, slots, fire","text":"Jaldapara elephant rides: Millennium Post (12 Jun 2026) reported six kunki elephants usable, with rides cancelled when one fell sick and two were pulled after a caretaker's death","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/jaldapara-national-park-elephant-shortage-forces-safari-cancellation-663979"}]},{"id":"08-227","topic":"news","ctx":"Parks and forests: closures, openings, fees, slots, fire","text":"Hollong Bungalow (built 1967) burned 18 Jun 2024 about 9:30 pm; short-circuit suspected; no injuries. Reconstruction formally began Feb 2026 (land handed to contractor), est. cost Rs 3.6 crore (earlier reports said Rs 3.8 crore, another said Rs 8 crore), eight rooms in concrete-and-wood, PWD supervising; no completion date.","kind":"report","src":[{"l":"Millennium Post, 17-18 Feb 2026","u":"https://www.millenniumpost.in/bengal/reconstruction-of-iconic-holong-forest-bungalow-begins-after-two-years-648633"},{"l":"The Week, 19 Jun 2024","u":"https://www.theweek.in/wire-updates/national/2024/06/19/cal31-wb-bungalow-fire.html"}]},{"id":"08-228","topic":"news","ctx":"Parks and forests: closures, openings, fees, slots, fire","text":"Buxa: tigress from Valmiki (Bihar) released 2 Oct 2026; restrictions in Buxa/Jayanti 30 Sep-9 Oct; limited reopening from 10 Oct (car safaris resumed, vehicles inside until 5 pm; overnight stays in registered homestays still restricted per guide).","kind":"report","src":[{"l":"Millennium Post, 10 Oct 2026","u":"https://www.millenniumpost.in/bengal/tiger-returns-to-buxa-but-tourism-curbs-hit-locals-679186"}]},{"id":"08-229","topic":"news","ctx":"Policy and projects","text":"Official document: \"The West Bengal Homestay Policy 2026\" (20-page PDF, text not extractable); says urban homestays registered under the 2022 policy are eligible for renewal under 2026","kind":"official","src":[{"l":"WB Tourism","u":"https://www.wbtourism.gov.in/assets/pdf/principal-notice/Final%20WB%20Homestay%20Policy%202026.pdf"}]},{"id":"08-230","topic":"news","ctx":"Policy and projects","text":"22 Oct 2026: state cabinet has approved a new homestay policy and a tourism industry policy, neither yet unveiled; police to list legal/illegal homestays in Darjeeling/Kalimpong; registration moving online; six-month digital tourism roadmap; Rs 57 crore central allocation; review of five ropeways.","kind":"report","src":[{"l":"ETV Bharat","u":"https://www.etvbharat.com/en/state/bengal-govt-outlines-six-month-roadmap-for-digital-revolution-infra-development-of-hill-tourism-enn26102206283"}]},{"id":"08-231","topic":"news","ctx":"Policy and projects","text":"July 2026: minister said drafting was under way, target Cabinet approval by August","kind":"report","src":[{"l":"ETV Bharat","u":"https://www.etvbharat.com/en/state/bengal-to-introduce-homestay-tourism-industrial-policies-by-august-enn26071102440"}]},{"id":"08-232","topic":"news","ctx":"Policy and projects","text":"1 Oct 2026: report of a Centre tourism push for West Bengal","kind":"report","src":[{"l":"The Week","u":"https://www.theweek.in/news/india/2026/10/01/west-bengal-set-for-major-tourism-push-from-centre-in-the-near-future.html"}]},{"id":"08-233","topic":"news","ctx":"Policy and projects","text":"Trains: Howrah-Kamakhya Vande Bharat Sleeper inaugurated 17 Jan 2026, stops at New Alipurduar and New Cooch Behar","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Kamakhya%E2%80%93Howrah_Vande_Bharat_Sleeper_Express"},{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Panvel%E2%80%93Alipurduar_Amrit_Bharat_Express"}]},{"id":"08-234","topic":"news","ctx":"Policy and projects","text":"Bhutan rail: Rs 4,033 crore, about 89 km, Kokrajhar-Gelephu and Banarhat-Samtse (Banarhat is in the Dooars); announced Sep 2025; progress noted Mar 2026; completion reportedly years away","kind":"report","src":[{"l":"BorderLens, 29 Mar 2026","u":"https://www.borderlens.com/2026/03/29/rail-link-to-mindfulness-city-bhutans-gelephu-vision-draws-closer-to-india/"},{"l":"IBEF","u":"https://www.ibef.org/news/india-bhutan-to-connect-by-rail-for-the-first-time-with-total-outlay-of-rs-4-033-crore-us-454-million"}]},{"id":"08-235","topic":"news","ctx":"Policy and projects","text":"Bhutan fees for Indians: SDF Rs 1,200 per person per night, under-6 free, 6-12 half; no SDF for stays up to 24 hours in Phuentsholing, Samtse, Gelephu, Samdrup Jongkhar; day visitors to Phuentsholing need a one-time online pre-registration (QR code); beyond Rinchending checkpost needs SDF and permit.","kind":"official","src":[{"l":"Indian Consulate Phuentsholing","u":"https://www.cgiphuentsholing.gov.in/page/guidelines-for-indians-visiting-bhutan/"},{"l":"Foundbht","u":"https://foundbht.com/travel-info/bhutan-sdf"}]},{"id":"08-236","topic":"news","ctx":"Events and festivals","text":"20th World Dooars Utsav, Alipurduar Parade Ground: opened 30 Dec 2025, ran to 10 Jan 2026; 1,000+ stalls including Nepal and Bhutan; 10,000+ artists; inaugurated by North Bengal Development Minister Udayan Guha (previous government)","kind":"report","src":[{"l":"Millennium Post, 31 Dec 2025","u":"https://www.millenniumpost.in/bengal/culture-and-tourism-in-focusas-world-dooars-utsav-opens-641970"},{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/alipurduar-18th-dooars-utsav-to-commence-from-dec-28-544160"}]},{"id":"08-237","topic":"news","ctx":"Events and festivals","text":"Planned for Darjeeling hills: tea festival, vintage car rally, river rafting, paragliding (no dates)","kind":"report","src":[{"l":"ETV Bharat, 22 Oct 2026","u":"https://www.etvbharat.com/en/state/bengal-govt-outlines-six-month-roadmap-for-digital-revolution-infra-development-of-hill-tourism-enn26102206283"}]},{"id":"08-238","topic":"news","ctx":"Events and festivals","text":"Durga Puja 2026 season bookings: strong per Millennium Post (18 Sep 2026); weak per Uttarbanga Sambad (18 Oct 2026). See section 6.","kind":"report","src":[]},{"id":"08-239","topic":"news","ctx":"Local business news","text":"Varnabari and Kohinoor tea gardens (Alipurduar) stopped work after Durga Puja 2026 amid unpaid bonuses; lockout notice; about 3,000 workers affected; no reopening found (Bengali report, late Oct 2026)","kind":"report","src":[{"l":"KolkataTV","u":"https://kolkatatvonline.in/west-bengal/dooars-two-tea-gardens-closed-alipurduar-workers-crisis-kolkatatv-online-district-news/"}]},{"id":"08-240","topic":"news","ctx":"Local business news","text":"Closure of 3 Dooars gardens, 2,000+ workers (2025, date from URL ID only)","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/closure-of-3-dooars-tea-gardens-leaves-over-2k-workers-in-crisis-627132"}]},{"id":"08-241","topic":"news","ctx":"Local business news","text":"Bengal Association of Hoteliers and Tour Operators (Kinkar Roy) wants online jeep booking at Chilapata and Jaldapara; Alipurduar District Hotel and Resort Association (Pawan Purohit) submitted development proposals (18 Sep 2026)","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/durga-puja-vacation-rush-strong-tourist-bookings-reported-in-dooars-676407"}]},{"id":"08-242","topic":"news","ctx":"Local business news","text":"Eastern Dooars Tourism Development Association (Bishwajit Saha) and Dooars Tourism Development Welfare Society (Biplab De) on flood losses and SIR effect (Dec 2025)","kind":"operator","src":[{"l":"Travel And Tour World","u":"https://www.travelandtourworld.com/news/article/dooars-winter-tourism-sees-revival-after-devastating-floods-offering-hope-for-a-stronger-2026-season/"}]},{"id":"08-243","topic":"news","ctx":"Visitor trends and sentiment","text":"Winter 2025-26 near-full occupancy, then a post-26 Dec dip of about 50% in some areas (29 Dec 2025)","kind":"operator","src":[{"l":"Travel And Tour World","u":"https://www.travelandtourworld.com/news/article/dooars-winter-tourism-sees-revival-after-devastating-floods-offering-hope-for-a-stronger-2026-season/"}]},{"id":"08-244","topic":"news","ctx":"Visitor trends and sentiment","text":"Puja 2026: operators reported good bookings (18 Sep 2026)","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/durga-puja-vacation-rush-strong-tourist-bookings-reported-in-dooars-676407"},{"l":"Uttarbanga Sambad","u":"https://uttarbangasambad.com/dooars-tourism-crisis-dooars-tourism-crisis-durga-puja-alipurduar/"}]},{"id":"08-245","topic":"news","ctx":"Visitor trends and sentiment","text":"Brokers charged Rs 4,000+ for jeeps in May 2026 during the fee waiver (Telegraph, via guide)","kind":"report","src":[{"l":"Offbeatpeak","u":"https://offbeatpeak.com/destination/dooars-safari-booking-guide/"}]},{"id":"08-246","topic":"news","ctx":"Safety, wildlife and conservation","text":"Buxa tigress released 2 Oct 2026 (above)","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/tiger-returns-to-buxa-but-tourism-curbs-hit-locals-679186"}]},{"id":"08-247","topic":"news","ctx":"Safety, wildlife and conservation","text":"Flood wildlife deaths and ten swept-away rhinos returned (Oct 2025, conflicting counts above).","kind":"report","src":[]},{"id":"08-248","topic":"news","ctx":"Safety, wildlife and conservation","text":"Rail-collision elephant death at Chapramari in 2023 (historical context)","kind":"report","src":[]},{"id":"10-249","topic":"official","ctx":"Visitor numbers (Jaldapara, Gorumara, Buxa, Chilapata, Neora Valley)","text":"Official WB government page (wb.gov.in, \"Visitors / Areas to visit - Forests\") calls Gorumara the state's most visited national park, but gives no figures and no fees, and does not mention Chilapata. It gives Buxa as 117 sq km (page text) and Neora Valley as 88 sq km.","kind":"official","src":[{"l":"wb.gov.in","u":"https://wb.gov.in/visitors-areas-to-visit-Forests.aspx"},{"l":"alipurduar.gov.in tourist places","u":"https://alipurduar.gov.in/tourist-places/"}]},{"id":"10-250","topic":"official","ctx":"Visitor numbers (Jaldapara, Gorumara, Buxa, Chilapata, Neora Valley)","text":"A search snippet mentioned an undated ~45,000 annual visitors for Jaldapara from a protected-areas listing; conflicts with 1.77 lakh and is unverified. Not used.","kind":"report","src":[]},{"id":"10-251","topic":"official","ctx":"Fees, safari details, booking, closures","text":"A news report (undated in snippet; URL slug refers to charges applying \"from September 16\") says new elephant safari rates are Rs 1,000 at Jaldapara and Rs 1,200 at Gorumara (from Rs 900 and Rs 1,020), with a uniform Rs 350 guide rate across north Bengal forests including Gorumara, Jaldapara, Buxa and Senchal.","kind":"report","src":[{"l":"Telegraph/ttef.in","u":"https://obeta.ttef.in/west-bengal/tourists-to-reserve-forests-across-bengal-to-pay-extra-to-avail-of-various-services-from-september-16/cid/1966021"}]},{"id":"10-252","topic":"official","ctx":"Fees, safari details, booking, closures","text":"Parks generally close mid-June to mid-September for the monsoon/breeding season, reopening about 16 September (search snippets from operator sites, unverified; not official).","kind":"report","src":[]},{"id":"10-253","topic":"official","ctx":"Fees, safari details, booking, closures","text":"Gorumara elephant safari tickets are reportedly not sold at counters (operator source, unverified).","kind":"report","src":[]},{"id":"10-254","topic":"official","ctx":"District data","text":"Jalpaiguri: area 3,386.18 sq km; population 2,381,596 (Census 2011); density 701/sq km; 3 sub-divisions; 9 blocks (Jalpaiguri Sadar, Dhupguri, Maynaguri, Rajganj, Mal, Matiali, Nagrakata, Kranti, Banarhat); 80 gram panchayats; 29 forest villages; page last updated 21.02.2024; no tea-garden data on page.","kind":"official","src":[{"l":"jalpaiguri.gov.in/district-statistics","u":"https://jalpaiguri.gov.in/district-statistics/"}]},{"id":"10-255","topic":"official","ctx":"District data","text":"Jalpaiguri attractions on homepage: Gorumara, Baikunthapur Forest, Murti, Jatileshwar Temple, Jalpesh, etc.","kind":"official","src":[{"l":"jalpaiguri.gov.in","u":"https://jalpaiguri.gov.in"}]},{"id":"10-256","topic":"official","ctx":"District data","text":"Alipurduar: area 3,136 sq km; population 15,01,983 (Census 2011); 6 blocks (Madarihat-Birpara, Alipurduar-I, Alipurduar-II, Falakata, Kalchini, Kumargram).","kind":"official","src":[{"l":"alipurduar.gov.in","u":"https://alipurduar.gov.in"}]},{"id":"10-257","topic":"official","ctx":"District data","text":"Alipurduar official tourist places: Jayanti, Chilapata, Raymatang, Jaigaon, Totopara, Rajabhatkhawa, Buxa Tiger Reserve (about 760 sq km), Jaldapara.","kind":"official","src":[{"l":"alipurduar.gov.in/tourist-places","u":"https://alipurduar.gov.in/tourist-places/"}]},{"id":"10-258","topic":"official","ctx":"District data","text":"Cooch Behar: area 3,387 sq km; population 28,19,086; 12 blocks (not named on homepage).","kind":"official","src":[{"l":"coochbehar.gov.in","u":"https://coochbehar.gov.in"}]},{"id":"10-259","topic":"official","ctx":"District data","text":"Cooch Behar's own \"Dooars Areas\" page does not list any Cooch Behar blocks as Dooars; it says the Dooars \"forms a major part of Jalpaiguri district\" and mentions Chilapata Forest and Nalrajar Garh as on the way to Cooch Behar, plus Hasimara.","kind":"official","src":[{"l":"coochbehar.gov.in/dooars-areas","u":"https://coochbehar.gov.in/dooars-areas/"}]},{"id":"10-260","topic":"official","ctx":"District data","text":"Cooch Behar tourist places page lists Rasik Bill and Madan Mohan Temple (partial).","kind":"official","src":[{"l":"coochbehar.gov.in/tourist-places","u":"https://coochbehar.gov.in/tourist-places/"}]},{"id":"10-261","topic":"official","ctx":"Tea estates, workers, closed gardens","text":"Lok Sabha USQ 2834, answered 18.03.2025, Commerce Ministry (Tea Board data as of Jan 2025): reportedly 185 registered tea estates in Jalpaiguri, 62 in Alipurduar, 449 in North Bengal. UNVERIFIED (search-result summary only).","kind":"official","src":[{"l":"commerce.gov.in PDF","u":"https://www.commerce.gov.in/wp-content/uploads/2025/03/LS-USQ-No.2834-dated.-18.03.2025.pdf"}]},{"id":"10-262","topic":"official","ctx":"Tea estates, workers, closed gardens","text":"Lok Sabha reply of 11 February 2025 (MoS Jitin Prasada): 6 closed gardens in Jalpaiguri, 10 in Alipurduar. State Labour department data: 2 closed in Jalpaiguri (Sonali, Raipur), 3 in Alipurduar (Ramjhora, Lankapara, Dheklapara).","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/tea-industry-reacts-to-centres-misleading-data-on-closed-gardens-599358"}]},{"id":"11-263","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"Cooch Behar Rash Mela: held on Rash Purnima, Nov-Dec, typically 15-20 days; organised by Cooch Behar Municipality and Debuttor Trust Board; began c. 1783-1839 under Maharaja Harendra Narayan (per Rajyopakhyan).","kind":"report","src":[{"l":"Wikipedia: Cooch Behar Rash Mela","u":"https://en.wikipedia.org/wiki/Cooch_Behar_Rash_Mela"}]},{"id":"11-264","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"2025 edition: Ras Purnima on 5 Nov 2025; Madan Mohan Mandir Ras Utsav described as \"213 years old\"; a 15-day mela began that day","kind":"official","src":[{"l":"All India Radio News, 5 Nov 2025","u":"https://www.newsonair.gov.in/ras-purnima-celebrated-across-west-bengal-with-processions-melas-and-devotional-fervour"}]},{"id":"11-265","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"Mela duration was reportedly extended from 15 to 20 days by the municipality, then a later report says shortened to 15 days","kind":"report","src":[{"l":"Millennium Post (shortened to 15 days)","u":"https://www.millenniumpost.in/bengal/cooch-behars-raas-mela-to-be-shortened-to-15-days-instead-of-the-usual-20-day-fair-581853"}]},{"id":"11-266","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"Kartik Purnima 2026 is Tuesday 24 Nov 2026 (Purnima tithi 11:42 PM 23 Nov to 8:23 PM 24 Nov IST, New Delhi)","kind":"official","src":[{"l":"Hindutone via Drik Panchang","u":"https://hindutone.com/festivals/kartika-purnima-2026-tripurari-purnima-dev-deepawali-date-significance-varanasi/"},{"l":"SmartPuja","u":"https://www.smartpuja.com/blog/kartik-purnima-2026/"}]},{"id":"11-267","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"Tihar 2026 (Nepal calendar): Kaag Tihar 7 Nov, Laxmi Puja and Kukur Tihar 8 Nov, Govardhan Puja 10 Nov, Bhai Tika 11 Nov 2026 (Kartik 21-25, 2083 BS); one guide gives Bhai Tika 10 Nov, likely an error","kind":"operator","src":[{"l":"Calendarific Nepal 2026","u":"https://www.calendarific.com/holidays/2026/NP"},{"l":"OfficeHolidays","u":"https://www.officeholidays.com/holidays/nepal/laxmi-puja"}]},{"id":"11-268","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"Magh Bihu 2027: 14 Jan 2027 per Calendarlabs and datesandtimes.org; 15 Jan 2027 per OfficeHolidays (Assam). Sources disagree; Uruka (eve) would be the night before. No Dooars-specific Bhogali Bihu source found.","kind":"operator","src":[{"l":"Calendarlabs","u":"https://www.calendarlabs.com/holidays/india/makar-sankranti.php"},{"l":"OfficeHolidays (Assam)","u":"https://www.officeholidays.com/holidays/india/assam/sankranti"}]},{"id":"11-269","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"World Dooars Utsav, Alipurduar: 19th edition opened early Jan 2025, ran to 12 Jan (11 days); BM Club Ground to Parade Ground procession; 1,000+ stalls incl. Nepal and Bhutan; main, children's and folk stages; 11,000+ artists (about 4,000 folk); showcases culture of 26 tribal communities","kind":"report","src":[{"l":"Millennium Post, Jan 2025","u":"https://www.millenniumpost.in/bengal/world-dooars-utsav-a-vibrant-celebration-of-culture-and-diversity-593222"},{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/18th-world-dooars-utsav-inaugurated-in-alipurduar-to-continue-till-jan-7-545959"}]},{"id":"11-270","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"Tea-Tribal Festival: two-day govt (Tribal Development dept) event opened 24 Jan 2024 at Newlands tea garden, Alipurduar; felicitation of tribal poets and tea-garden folk artists; reps of 64 gardens","kind":"report","src":[{"l":"Millennium Post, 2024","u":"https://www.millenniumpost.in/bengal/alipurduar-tea-tribal-festival-inaugurated-549531"}]},{"id":"11-271","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"Buxa tourism / cultural carnival, Alipurduar (Millennium Post, edition year unverified)","kind":"report","src":[{"l":"link","u":"https://www.millenniumpost.in/bengal/alipurduar-buxa-tourism-cultural-carnival-commences-547984"}]},{"id":"11-272","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"Bhawaiya: 2023 Bhawaiya Festival held in Jalpaiguri with singers from Cooch Behar, Alipurduar and Jalpaiguri; state-level Bhawaiya song competition at Dooars Utsav Maidan in 2015","kind":"report","src":[{"l":"Festivals from India","u":"https://festivalsfromindia.com/festival-detail/bhawaiya-festival"},{"l":"Business Standard/PTI 2015","u":"https://www.business-standard.com/article/pti-stories/bhawaiya-song-competition-inaugurated-115020700678_1.html"}]},{"id":"11-273","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"Karam: described as a harvest festival of Adivasi/tea-tribe communities in WB and Assam; Jitiya Karam on Shukla Ekadashi in Bhadra (Aug-Sep)","kind":"report","src":[{"l":"Sentinel Assam","u":"https://www.sentinelassam.com/more-news/editorial/karam-puja-the-sacred-rhythm-of-assams-tea-tribes"},{"l":"Telegraph/ttef.in","u":"https://obeta.ttef.in/west-bengal/north-bengal-adivasis-seek-tmc-government-grant-for-karam-puja/cid/2044788"}]},{"id":"11-274","topic":"culture","ctx":"Festivals (community, month, location, what visitors see","text":"Tea-estate Kali Puja at Dheklapara, Alipurduar (century-old, storm-funded)","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/how-a-storm-funded-century-old-kali-puja-in-dheklapara-a-tea-estate-in-alipurduar/cid/2059717"},{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/shut-tea-gardens-appreciate-governments-durga-puja-grant-helpful-for-workers-with-no-salary/cid/2053934"}]},{"id":"11-275","topic":"culture","ctx":"Census 2011 ST population","text":"Undivided Jalpaiguri (2011): 38,72,846 population, 7,31,704 ST (about 18.9%), highest ST count in West Bengal","kind":"report","src":[{"l":"Visva-Bharati study snippet via search","u":"https://ir.vidyasagar.ac.in/bitstream/123456789/4531/1/P.%20Deb.pdf"}]},{"id":"11-276","topic":"culture","ctx":"Census 2011 ST population","text":"Alipurduar (2011): population 14,91,250; ST 3,82,112 (25.62%); SC 4,56,706 (30.62%); mother tongue Bengali 53.93%, Sadri 16.80%, Nepali 9.70%, Rajbongshi 3.17%","kind":"report","src":[{"l":"Wikipedia: Alipurduar district","u":"https://en.wikipedia.org/wiki/Alipurduar_district"}]},{"id":"11-277","topic":"culture","ctx":"Census 2011 ST population","text":"Jalpaiguri (post-split, 2011): population 23,81,596; ST 3,49,592 (14.68%); SC 10,01,572 (42.05%); Bengali 65.57%, Sadri 12.96%, Nepali 4.90%, Hindi 4.69%, Rajbongshi 2.69%, Kurukh 1.39%; Hindu 82.41%, Muslim 13.25%, Christian 3.12%, Buddhist 0.64%","kind":"report","src":[{"l":"Wikipedia: Jalpaiguri district","u":"https://en.wikipedia.org/wiki/Jalpaiguri_district"}]},{"id":"11-278","topic":"culture","ctx":"Census 2011 ST population","text":"Check: 3,82,112 + 3,49,592 = 7,31,704, matching the undivided figure.","kind":"report","src":[]},{"id":"11-279","topic":"culture","ctx":"Census 2011 ST population","text":"Cooch Behar (2011): population 28,19,086; SC 14,14,336 (50.17%, the only Indian district with an SC majority per the article); ST 18,125 (0.64%); Bengali 94.79%, Rajbongshi 1.31% (Kamtapuri not listed as a category)","kind":"report","src":[{"l":"Wikipedia: Cooch Behar district","u":"https://en.wikipedia.org/wiki/Cooch_Behar_district"}]},{"id":"11-280","topic":"culture","ctx":"Census 2011 ST population","text":"Undivided Jalpaiguri ST shares: Oraon 50.35%, Munda 11.78%, Santal 5.31% (together about 67.4%)","kind":"report","src":[{"l":"Visva-Bharati/Salesian College study","u":"https://publications.salesiancollege.net/wp-content/uploads/2022/07/Tribal-Economy-Change-A-Special-Focus-on-Oraon-Munda-Santal-Tribes-in-Jalpaiguri.pdf"}]},{"id":"11-281","topic":"culture","ctx":"Census 2011 ST population","text":"Toto: 1,389 counted in 2011 (171 in 1901; 1,175 in 2001); Toto Kalyan Samiti reported 1,616 (not Census)","kind":"report","src":[{"l":"The Federal, 23 Mar 2021","u":"https://thefederal.com/the-eighth-column/a-small-tribes-struggle-to-balance-development-and-cultural-identity"},{"l":"Wikipedia: Totopara","u":"https://en.wikipedia.org/wiki/Totopara"}]},{"id":"11-282","topic":"culture","ctx":"Census 2011 ST population","text":"Census 2011 does not give community-wise ST figures for the then-new Alipurduar district at district level, per a Jalpaiguri study snippet.","kind":"report","src":[]},{"id":"11-283","topic":"culture","ctx":"Food","text":"Totopara homes keep bamboo-fenced kitchen gardens (vegetables, potatoes, bananas); \"Eu\" is named as a worship offering","kind":"report","src":[{"l":"Wikipedia: Toto people","u":"https://en.wikipedia.org/wiki/Toto_people"}]},{"id":"11-284","topic":"culture","ctx":"Food","text":"Totos grow maize and betel nut and trade Bhutanese goods","kind":"report","src":[{"l":"The Federal 2021","u":"https://thefederal.com/the-eighth-column/a-small-tribes-struggle-to-balance-development-and-cultural-identity"}]},{"id":"11-285","topic":"culture","ctx":"Music, dance and crafts; GI status","text":"Toto script: developed by Dhaniram Toto in 2015; Unicode accepted proposal 8 Oct 2019; in Unicode 14.0 (Sept 2021); Padma recognition reported in 2023 (Times of India)","kind":"report","src":[{"l":"Wikipedia: Toto people","u":"https://en.wikipedia.org/wiki/Toto_people"},{"l":"The Federal 2021","u":"https://thefederal.com/the-eighth-column/a-small-tribes-struggle-to-balance-development-and-cultural-identity"}]},{"id":"11-286","topic":"culture","ctx":"Music, dance and crafts; GI status","text":"Bhawaiya: folk music of Cooch Behar, Jalpaiguri, parts of Darjeeling, North Dinajpur and Assam","kind":"report","src":[{"l":"Festivals from India","u":"https://festivalsfromindia.com/festival-detail/bhawaiya-festival"}]},{"id":"11-287","topic":"culture","ctx":"Totopara visitor access","text":"Totopara is a single-lane road from NH31 via Hantapara, about 22 km from Madarihat (entry to Jaldapara NP)","kind":"report","src":[{"l":"Wikipedia: Totopara","u":"https://en.wikipedia.org/wiki/Totopara"}]},{"id":"11-288","topic":"culture","ctx":"Totopara visitor access","text":"State-supported homestays strengthened the local economy; COVID halted guests for over a year (operator Bhabesh Toto)","kind":"report","src":[{"l":"The Federal 2021","u":"https://thefederal.com/the-eighth-column/a-small-tribes-struggle-to-balance-development-and-cultural-identity"}]},{"id":"11-289","topic":"culture","ctx":"Totopara visitor access","text":"West Bengal tourism pages list Toto Para as ethnic tourism and give the Jaldapara Tourist Lodge and DFO Cooch Behar contact; no visitor rules","kind":"report","src":[{"l":"wildbengal.com","u":"https://wildbengal.com/jaldapara-np.php"}]},{"id":"11-290","topic":"culture","ctx":"Totopara visitor access","text":"A commercial guide says the forest is closed 15 Jun-15 Sep (verify)","kind":"operator","src":[{"l":"north-bengal.com","u":"https://north-bengal.com/madarihat-dooars.php"}]},{"id":"11-291","topic":"culture","ctx":"Totopara visitor access","text":"Inner Line Permit applies only to Arunachal, Nagaland, Mizoram and Manipur (general knowledge from Wikipedia: Inner Line Permit); not to West Bengal, so no ILP is implied.","kind":"report","src":[{"l":"Wikipedia: Inner Line Permit","u":"https://en.wikipedia.org/wiki/Inner_Line_Permit"}]},{"id":"12-292","topic":"places","ctx":"Totopara","text":"Village in Madarihat-Birpara CD block, Alipurduar subdivision/district; Madarihat police station; 26°50'N 89°19'E; bounded by Bhutan foothills (N), Torsa river (E), Titi reserve forest (SW) across the Hauri river; nearest village Ballalguri ~5 km south; area 8.08 sq km; 2011 population 2,960","kind":"report","src":[{"l":"Wikipedia Totopara, acc. 2026","u":"https://en.wikipedia.org/wiki/Totopara"}]},{"id":"12-293","topic":"places","ctx":"Totopara","text":"About 22 km from Madarihat via a single-lane motorable road from NH 31 through Hantapara","kind":"operator","src":[{"l":"Wikipedia Totopara, acc. 2026","u":"https://en.wikipedia.org/wiki/Totopara"},{"l":"north-bengal.com Madarihat, acc. 2026","u":"https://north-bengal.com/madarihat-dooars.php"}]},{"id":"12-294","topic":"places","ctx":"Totopara","text":"Toto population was 321 in 1951 and 1,184 in 2001 (all in Totopara) after measures to keep outsiders from swamping their area; language/culture distinct from Rajbongshi, Koch, Mech, Sharchop","kind":"official","src":[{"l":"Alipurduar district site, updated 3 May 2023","u":"https://alipurduar.gov.in/?p=28695"}]},{"id":"12-295","topic":"places","ctx":"Totopara","text":"Official district page lists access: Bagdogra airport; trains to Falakata, Alipurduar Jn or New Alipurduar; roads from Siliguri, Cooch Behar, Falakata, Alipurduar. It does not state permits, accommodation or distances (separate Accommodation page and a Certified Tourist Guide List PDF exist on the site, not read)","kind":"official","src":[{"l":"alipurduar.gov.in, 2023","u":"https://alipurduar.gov.in/?p=28695"}]},{"id":"12-296","topic":"places","ctx":"Totopara","text":"Road reported as rough with shallow river crossings that can flood in monsoon and cut off the village","kind":"operator","src":[{"l":"blog, 2015","u":"https://week-end-tour.blogspot.com/2015/09/totopara-lankapara.html"}]},{"id":"12-297","topic":"places","ctx":"Madarihat / Hasimara","text":"Madarihat: own station on the NJP-Alipurduar line; Alipurduar Jn ~50 km, Siliguri ~125 km (~3 h), Bagdogra ~135 km; entry point to Jaldapara NP; Totopara ~22 km; South Khairbari Nature Park (rescued tigers/leopards) nearby; Phuentsholing ~45 km; WBTDC Madarihat Tourist Lodge near the Jaldapara entrance.","kind":"operator","src":[{"l":"north-bengal.com, acc. 2026","u":"https://north-bengal.com/madarihat-dooars.php"}]},{"id":"12-298","topic":"places","ctx":"Madarihat / Hasimara","text":"Hasimara is 45 km from Alipurduar and 60 km from Cooch Behar; WBFDC Malangi Lodge (Barodabari, Hasimara, Birpara-Madarihat block) is within 8 km of Hasimara station and 37 km of New Alipurduar; Siliguri ~160 km, Bagdogra ~150 km by that lodge's reckoning","kind":"official","src":[{"l":"WBFDC Alipurduar page, acc. 2026","u":"https://wbfdc.net/Alipurduar"}]},{"id":"12-299","topic":"places","ctx":"Madarihat / Hasimara","text":"WBFDC Mendabari Jungle Lodge (inside Jaldapara, Dakshin Barajhar): ~12 km from Hasimara station, ~20 km from Alipurduar Jn","kind":"official","src":[{"l":"WBFDC, acc. 2026","u":"https://wbfdc.net/Alipurduar"}]},{"id":"12-300","topic":"places","ctx":"Madarihat / Hasimara","text":"Another blog states Madarihat is 12 km from Hasimara","kind":"operator","src":[{"l":"web search summary of travel blog, acc. 2026","u":"https://week-end-tour.blogspot.com/2015/09/totopara-lankapara.html"}]},{"id":"12-301","topic":"places","ctx":"Gajoldoba","text":"Village in Rajganj CD block, Jalpaiguri district; 26.7515°N 88.5856°E; Teesta Barrage built 1985 by Jessop & Co for irrigation; reservoir is a bird-watching centre; Baikunthapur forest surrounds it","kind":"report","src":[{"l":"Wikipedia Gajoldoba, acc. 2026","u":"https://en.wikipedia.org/wiki/Gajoldoba"}]},{"id":"12-302","topic":"places","ctx":"Gajoldoba","text":"Common figure ~25 km from Siliguri (~1 h), ~40 km from Jalpaiguri; one guide says 10 km and another ~30 km","kind":"operator","src":[{"l":"Outlook Traveller","u":"https://www.outlooktraveller.com/News/shikara-sails-its-way-to-west-bengal"},{"l":"1001things","u":"https://1001things.org/gajoldoba/"}]},{"id":"12-303","topic":"places","ctx":"Gajoldoba","text":"State government move to develop viewpoints and brand it a bird sanctuary \"Pakhibitan\" (reported 2024)","kind":"report","src":[{"l":"Telegraph/ttef, 2024","u":"https://obeta.ttef.in/west-bengal/gajoldoba-to-get-new-view-points-under-bengal-governments-tourism-boost-for-jalpaiguri/cid/1975882"}]},{"id":"12-304","topic":"places","ctx":"Gajoldoba","text":"Barrage foundation date conflict: 1985 (Wikipedia) vs foundation stone 19 Jan 1987 (a blog snippet)","kind":"report","src":[]},{"id":"12-305","topic":"places","ctx":"Rasikbil (Cooch Behar)","text":"Wetland/lake in Tufanganj subdivision, Cooch Behar; 26°24'50\"N 89°43'30\"E; ~7.5 km from Kamakhyaguri (nearest station); birds incl. cormorants, storks, ibises, spoonbills, lesser whistling duck, teal, pintail; deer park, crocodile rehabilitation centre, aviary, watch tower","kind":"report","src":[{"l":"Wikipedia Rasikbil, acc. 2026","u":"https://en.wikipedia.org/wiki/Rasikbil"}]},{"id":"12-306","topic":"places","ctx":"Rasikbil (Cooch Behar)","text":"175 ha; ~30 min from Tufanganj; best Sept-March; open daily except Thursday ~9 am-5 pm, tickets at counter; no homestays nearby; \"Rasikbill Nature Education and Wilderness Resort\" run by WBFDC","kind":"operator","src":[{"l":"northbengaltourism.com, acc. 2026","u":"https://northbengaltourism.com/rasikbill"}]},{"id":"12-307","topic":"places","ctx":"Rasikbil (Cooch Behar)","text":"Station conflict: Kamakhyaguri ~6 km (same page) vs New Cooch Behar named in FAQ; Wikipedia says 7.5 km from Kamakhyaguri. Distance to Cooch Behar town given as 15, 35 and 45 km in different tourism sites","kind":"operator","src":[{"l":"Explurger","u":"https://www.explurger.com/pd/w1whgqk9dmsi0nu1z"},{"l":"north-bengal.com","u":"https://north-bengal.com/rasikbil-dooars.html"}]},{"id":"12-308","topic":"places","ctx":"Mal Bazar / Chalsa","text":"Malbazar is a subdivision town (Jalpaiguri); ~55 km from Siliguri, ~65 km from Jalpaiguri (dooars.info); Bagdogra ~74 km; Gorumara NP ~16 km (~30 min); two stations: New Mal Junction (NMZ, express/intercity) and Malbazar (MLBZ, locals/DEMU); New Mal Jn to NJP ~35 km per RailYatri","kind":"operator","src":[{"l":"Wikipedia Malbazar","u":"https://en.wikipedia.org/wiki/Malbazar"},{"l":"dooars.info","u":"https://dooars.info/?p=3094"}]},{"id":"12-309","topic":"places","ctx":"Mal Bazar / Chalsa","text":"Chalsa has its own railway station; most long-distance trains do not stop at Chalsa/Nagrakata","kind":"operator","src":[{"l":"north-bengal.com Jhalong, acc. 2026","u":"https://www.north-bengal.com/jhalong-dooars.php"},{"l":"Expedia Chalsa, acc. 2026","u":"https://www.expedia.com.au/Chalsa.dx6130819"}]},{"id":"12-310","topic":"places","ctx":"Hills/foothills: Jhalong, Bindu, Paren, Samsing, Suntalekhola","text":"Jhalong \"within Kalimpong District\"; ~100 km from NJP/Bagdogra (2.5-3 h) via NH17, turn at Khunia More (10 min from Chalsa/Nagrakata), then Chapramari (12 km), Kumani, Naxal Bridge, Jhalong Bazaar; Bindu dam ~10 km north; Jaldhaka Dam (Bindu barrage) completed 1967; WBFDC Jhalong River Camp (cottages); Humro Home community homestays at Paren/Jhalong/Bindu.","kind":"operator","src":[{"l":"north-bengal.com Jhalong, acc. 2026","u":"https://www.north-bengal.com/jhalong-dooars.php"},{"l":"darjeeling-tourism.com","u":"https://darjeeling-tourism.com/darj_000214.htm"}]},{"id":"12-311","topic":"places","ctx":"Hills/foothills: Jhalong, Bindu, Paren, Samsing, Suntalekhola","text":"Samsing: Matiali CD block, Malbazar subdivision, Jalpaiguri district; 26.9901°N 88.8117°E; ~914 m; Samsing Tea Estate on the Murti river (1,200 ha, work suspended 28 Nov 2005, 1,360 workers per Wikipedia — status may have changed); 18 km from Neora Valley NP; Suntalekhola and Rocky Island listed as picnic spots","kind":"operator","src":[{"l":"Wikipedia Samsing, acc. 2026","u":"https://en.wikipedia.org/wiki/Samsing"},{"l":"north-bengal.com Samsing","u":"https://north-bengal.com/samsing-dooars.php"}]},{"id":"12-312","topic":"places","ctx":"Hills/foothills: Jhalong, Bindu, Paren, Samsing, Suntalekhola","text":"Neora Valley NP: Kalimpong subdivision, 88 sq km, up to 3,200 m at Rachela Pass; ~105 km from NJP via Coronation Bridge, NH-31, Odlabari, Damdim, Gorubathan to Lava, then ~10 km; open 16 Sep-15 Jun, closed ~3 months in monsoon; best Oct-Apr; homestays at Lava and Kolakham","kind":"operator","src":[{"l":"northbengaltourism.com, acc. 2026","u":"https://northbengaltourism.com/neora-valley-national-park"}]},{"id":"12-313","topic":"places","ctx":"Tea estates","text":"Estates on the Chalsa-Samsing route include Aibheel, Samsing and Chalouni; route passes Looksan village","kind":"report","src":[{"l":"Octavius Tea blog (promotional), acc. 2026","u":"https://octaviustea.digitalpress.blog/dooars-sightseeing/"}]},{"id":"12-314","topic":"places","ctx":"Tea estates","text":"Octavius Tea Resorts runs stays inside working estates: Nya Sylee heritage bungalow and Sylee Bungalow (Damdim, Jalpaiguri), packages with meals, tea and factory visit","kind":"report","src":[{"l":"Octavius blog","u":"https://octaviustea.digitalpress.blog/heritage-tea-estate-in-dooars/"},{"l":"Fueler listing","u":"https://fueler.io/octaviustearesorts/sylee-bungalow"}]},{"id":"12-315","topic":"places","ctx":"Duar War 1864-65 / Treaty of Sinchula","text":"1841: Britain annexed Assam Duars from Bhutan, paying Rs 10,000 annually; 1862 Bhutanese raids on Sikkim/Cooch Behar; Jan 1863 Ashley Eden mission reached Punakha, repudiated by Bhutan in April; war 1864-65","kind":"report","src":[{"l":"Wikipedia Duar War, acc. 2026","u":"https://en.wikipedia.org/wiki/Duar_War"}]},{"id":"12-316","topic":"places","ctx":"Duar War 1864-65 / Treaty of Sinchula","text":"Viceroy Lord Lawrence declared war Nov 1864 (one source gives 12 Nov 1864)","kind":"report","src":[{"l":"web summary of Wikipedia/gktoday","u":"https://gktoday.in/bhutan-war-1864-65"}]},{"id":"12-317","topic":"places","ctx":"Duar War 1864-65 / Treaty of Sinchula","text":"Treaty of Sinchula signed 11 Nov 1865 (Lt-Col Herbert Bruce for British India); Bhutan ceded the \"Eighteen Doars\" bordering Rungpoor, Cooch Behar, Assam, Ambaree Fallcottah and hill territory on the left bank of the Teesta; annual allowance rising from Rs 25,000 to Rs 50,000 (paid each 10 January); Bhutan lost roughly a fifth of its territory.","kind":"report","src":[{"l":"Wikipedia Duar War","u":"https://en.wikipedia.org/wiki/Duar_War"},{"l":"countrystudies.us/bhutan/9.htm","u":"https://countrystudies.us/bhutan/9.htm"}]},{"id":"12-318","topic":"places","ctx":"Duar War 1864-65 / Treaty of Sinchula","text":"Forts: Buxa captured by central column; Dalimkote by the third column; Dewangiri taken, lost, then retaken by Maj-Gen Henry Tombs","kind":"report","src":[{"l":"Wikipedia Duar War","u":"https://en.wikipedia.org/wiki/Duar_War"}]},{"id":"12-319","topic":"places","ctx":"Buxa Fort","text":"867 m, Buxa Tiger Reserve, Alipurduar district, ~30 km from Alipurduar; 26°45'17.86\"N 89°34'49.04\"E; Bhutanese outpost; formally handed to British 11 Nov 1865 and rebuilt in stone; detention camp 1930-37, special jail 1942-47 and 1949-51 per researcher Subhamay Dutta; Subhas Bose was not held there.","kind":"report","src":[{"l":"Wikipedia Buxa Fort, acc. 2026","u":"https://en.wikipedia.org/wiki/Buxa_Fort"},{"l":"indianpanorama","u":"https://www.indianpanorama.in/experiences/heritage/forts/buxa-fort.php"}]},{"id":"12-320","topic":"places","ctx":"Buxa Fort","text":"Rs 5 crore renovation sanctioned (reported 2024), restoration reported nearing completion","kind":"report","src":[{"l":"Telegraph/ttef 2024","u":"https://obeta.ttef.in/west-bengal/buxa-fort-to-get-a-makeover/cid/1793724"},{"l":"ttef","u":"https://obeta.ttef.in/west-bengal/buxa-fort-renovation-nears-end/cid/1863922"}]},{"id":"12-321","topic":"places","ctx":"Cooch Behar Rajbari (Victor Jubilee Palace)","text":"Most sources: built 1887 under Maharaja Nripendra Narayan, Italian Renaissance style (also said to be modelled on Buckingham Palace); one source says 1878 (minority, treat as error); now a museum","kind":"report","src":[{"l":"Square Yards blog","u":"https://squareyards.com/blog/cooch-behar-palace-mnm"},{"l":"Wikipedia mirror","u":"https://ipfs.ssi.eecc.de/ipns/en.wikipedia-on-ipfs.org/wiki/Cooch_Behar_Palace"}]},{"id":"12-322","topic":"places","ctx":"Bengal Dooars Railway","text":"Company formed 1891 in the UK, HQ Domohani, merged into Eastern Bengal Railway 1941; 1936 fleet 19 locomotives, 72 coaches, 473 goods wagons","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Bengal_Dooars_Railway"},{"l":"FIBIS wiki","u":"https://wiki.fibis.org/w/Bengal_Dooars_Railway"}]}];